fn test_wasm32_web_e2e_matches_php_foreach_iterator_aggregate_dynamic_interface_return() {
    assert_wasm_matches_php(
        "<?php\nclass AggDynA implements Iterator { private int $i; public function __construct() { $this->i = 1; } public function rewind(): void {} public function valid(): bool { return $this->i < 3; } public function current(): int { return $this->i; } public function key(): int { return $this->i - 1; } public function next(): void { $this->i = $this->i + 1; } }\nclass AggDynB implements Iterator { private int $i; public function __construct() { $this->i = 5; } public function rewind(): void {} public function valid(): bool { return $this->i < 7; } public function current(): int { return $this->i * 2; } public function key(): int { return $this->i - 5; } public function next(): void { $this->i = $this->i + 1; } }\nclass AggDyn implements IteratorAggregate { private bool $right; public function __construct(bool $right) { $this->right = $right; } public function getIterator(): Iterator { if ($this->right) { return new AggDynB(); } return new AggDynA(); } }\nforeach (new AggDyn(false) as $k => $v) { echo $k . \":\" . $v . \" \"; }\nforeach (new AggDyn(true) as $k => $v) { echo $k . \":\" . $v . \" \"; }\necho \"\\n\";\n",
    );
}

