fn test_wasm32_web_e2e_matches_php_interface_typed_assoc_array_return_transforms() {
    assert_wasm_matches_php(
        "<?php\ninterface MakesRows { public function rows(): array; }\nclass BoxRows implements MakesRows { public function rows(): array { return [\"name\" => \"box\", \"tail\" => \"end\"]; } }\nclass CubeRows implements MakesRows { public function rows(): array { return [\"name\" => \"cube\", \"tail\" => \"done\"]; } }\nfunction describe_rows(MakesRows $maker) { $values = array_values($maker->rows()); $keys = array_keys($maker->rows()); $reverse = array_reverse($maker->rows()); $slice = array_slice($maker->rows(), 0, 1, true); $merge = array_merge([\"kind\" => \"row\"], $maker->rows()); echo $values[0] . \":\" . $values[1] . \":\" . $keys[0] . \":\" . $reverse[\"tail\"] . \":\" . count($slice) . \":\" . $merge[\"kind\"] . \":\" . $merge[\"name\"] . \"\\n\"; }\ndescribe_rows(new BoxRows());\ndescribe_rows(new CubeRows());\n",
    );
}

