#[test]
fn test_wasm32_web_e2e_matches_php_parent_typed_assoc_array_return_key_set_transforms() {
    assert_wasm_matches_php(
        "<?php\nclass BaseRows { public function rows(): array { return [\"name\" => \"base\", \"tail\" => \"end\", \"drop\" => \"no\"]; } }\nclass BoxRows extends BaseRows { public function rows(): array { return [\"name\" => \"box\", \"tail\" => \"end\", \"drop\" => \"no\"]; } }\nclass CubeRows extends BaseRows { public function rows(): array { return [\"name\" => \"cube\", \"tail\" => \"done\", \"drop\" => \"no\"]; } }\nfunction describe_rows(BaseRows $maker) { $diff = array_diff_key($maker->rows(), [\"drop\" => true]); $intersect = array_intersect_key($maker->rows(), [\"name\" => true, \"tail\" => true]); echo count($diff) . \":\" . $diff[\"name\"] . \":\" . count($intersect); foreach ($intersect as $key => $value) { echo \":\" . $key . \"=\" . $value; } echo \"\\n\"; }\ndescribe_rows(new BoxRows());\ndescribe_rows(new CubeRows());\n",
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_interface_typed_assoc_array_return_numeric_folds() {
    assert_wasm_matches_php(
        "<?php\ninterface MakesScores { public function scores(): array; }\nclass BoxScores implements MakesScores { public function scores(): array { return [\"first\" => 2, \"second\" => 3]; } }\nclass CubeScores implements MakesScores { public function scores(): array { return [\"first\" => 4, \"second\" => 5]; } }\nfunction describe_scores(MakesScores $maker) { echo array_sum($maker->scores()) . \":\" . array_product($maker->scores()) . \"\\n\"; }\ndescribe_scores(new BoxScores());\ndescribe_scores(new CubeScores());\n",
    );
}

