#[test]
fn test_wasm32_web_e2e_matches_php_static_method_indexed_array_return_transforms() {
    assert_wasm_matches_php(
        "<?php\nclass StaticScores { public static function scores(): array { return [2, 3, 2]; } public static function one(): array { return [9]; } }\n$values = array_values(StaticScores::scores());\n$reverse = array_reverse(StaticScores::scores());\n$unique = array_unique(StaticScores::scores());\n$slice = array_slice(StaticScores::scores(), 1, 2);\n$merge = array_merge([1], StaticScores::scores());\n$pad = array_pad(StaticScores::scores(), 5, 9);\n$chunks = array_chunk(StaticScores::scores(), 2);\n$keys = array_rand(StaticScores::scores(), count(StaticScores::scores()));\necho count($values) . \":\" . $values[0] . \":\" . $reverse[0] . \":\" . count($unique) . \":\" . $slice[0] . \":\" . array_sum($merge) . \":\" . count($pad) . \":\" . $pad[4] . \":\" . count($chunks) . \":\" . $chunks[0][1];\necho \":\"; echo array_rand(StaticScores::one()); echo \":\" . count($keys);\nforeach ($unique as $i => $score) { echo \":\" . $i . \"=\" . $score; }\necho \"\\n\";\n",
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_static_method_assoc_array_return_transforms() {
    assert_wasm_matches_php(
        "<?php\nclass StaticRows { public static function rows(): array { return [\"name\" => \"box\", \"tail\" => \"end\", \"again\" => \"box\"]; } public static function one(): array { return [\"only\" => \"row\"]; } }\n$values = array_values(StaticRows::rows());\n$keys = array_keys(StaticRows::rows());\n$reverse = array_reverse(StaticRows::rows());\n$slice = array_slice(StaticRows::rows(), 0, 2, true);\n$merge = array_merge([\"kind\" => \"row\"], StaticRows::rows());\n$filter = array_filter(StaticRows::rows());\n$unique = array_unique(StaticRows::rows());\n$flip = array_flip(StaticRows::rows());\n$diff = array_diff(StaticRows::rows(), [\"end\"]);\n$intersect = array_intersect(StaticRows::rows(), [\"box\"]);\n$pad = array_pad(StaticRows::rows(), 5, \"pad\");\n$chunks = array_chunk(StaticRows::rows(), 2, true);\n$randKeys = array_rand(StaticRows::rows(), count(StaticRows::rows()));\n$strlenFilter = array_filter(StaticRows::rows(), \"strlen\");\necho $values[0] . \":\" . $values[1] . \":\" . $keys[0] . \":\" . $reverse[\"tail\"] . \":\" . count($slice) . \":\" . $merge[\"kind\"] . \":\" . $filter[\"name\"] . \":\" . count($unique) . \":\" . $flip[\"box\"] . \":\" . $diff[\"name\"] . \":\" . $intersect[\"again\"] . \":\" . count($pad) . \":\" . $pad[4] . \":\" . count($chunks) . \":\" . $chunks[0][\"tail\"];\necho \":\"; echo array_rand(StaticRows::one()); echo \":\" . count($randKeys) . \":\" . count($strlenFilter);\nforeach ($filter as $key => $value) { echo \":\" . $key . \"=\" . $value; }\necho \"\\n\";\n",
    );
}

