#[test]
fn test_wasm32_web_e2e_matches_php_object_trait_method_adaptations() {
    assert_wasm_matches_php(
        r#"<?php
trait FirstLabels {
    public function label(): string { return "first"; }
    public static function staticLabel(): string { return "static-first"; }
}
trait SecondLabels {
    public function label(): string { return "second"; }
    public static function staticLabel(): string { return "static-second"; }
}
trait SecretLabels {
    public function reveal(): string { return "visible"; }
}
class Box {
    use FirstLabels, SecondLabels {
        FirstLabels::label insteadof SecondLabels;
        SecondLabels::label as otherLabel;
        FirstLabels::staticLabel insteadof SecondLabels;
        SecondLabels::staticLabel as otherStaticLabel;
    }
    use SecretLabels {
        reveal as private hiddenReveal;
    }
    public function callHidden(): string { return $this->hiddenReveal(); }
}
$box = new Box();
echo $box->label() . ":" . $box->otherLabel() . ":";
echo Box::staticLabel() . ":" . Box::otherStaticLabel() . ":";
echo $box->reveal() . ":" . $box->callHidden() . "\n";
"#,
    );
}

