#[test]
fn test_wasm32_web_wat_static_object_property_uninitialized_read_traps() {
    let program = parse_program("<?php class Child {} class Box { public static Child $value; } echo get_class(Box::$value);");
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT should be UTF-8");

    assert!(wat.contains("_initialized"));
    assert!(wat.contains("unreachable"));
}

