#[test]
fn test_wasm32_web_object_private_constructor_is_rejected() {
    let program = parse_program("<?php class Box { private function __construct() {} } $o = new Box();");
    let err =
        generate(&program, WasmOutputFormat::Wat).expect_err("private constructor needs visibility metadata");

    assert!(
        err.message.contains("supported public fixed constructor")
            || err.message.contains("visible fixed constructor metadata")
    );
}

