fn test_wasm32_web_object_private_instance_member_access_is_rejected() {
    let property_program =
        parse_program("<?php class Box { private int $value = 1; } $o = new Box(); echo $o->value;");
    let property_err = generate(&property_program, WasmOutputFormat::Wat)
        .expect_err("private instance property access must stay rejected");
    assert!(property_err.message.contains("visible fixed property metadata"));

    let method_program = parse_program(
        "<?php class Box { private function value(): int { return 1; } } $o = new Box(); echo $o->value();",
    );
    let method_err = generate(&method_program, WasmOutputFormat::Wat)
        .expect_err("private instance method access must stay rejected");
    assert!(method_err.message.contains("visible fixed method metadata"));
}

