#[test]
fn test_wasm32_web_wat_output_string_builtins() {
    let program = parse_program(
        "<?php echo ord(\"A\"); echo strtolower(\"WEB\"); echo strtoupper(\"web\"); echo lcfirst(\"Web\"); echo ucfirst(\"web\"); echo strrev(\"abc\"); echo trim(\" web \"); echo ltrim(\" web\"); echo rtrim(\"web \"); echo str_repeat(\"ab\", 2); echo substr(\"abcdef\", 1, 3);",
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT output was not UTF-8");

    assert!(wat.contains("i64.const 65"));
    assert!(wat.contains("web"));
    assert!(wat.contains("WEB"));
    assert!(wat.contains("cba"));
    assert!(wat.contains("abab"));
    assert!(wat.contains("bcd"));
}

