#[test]
fn test_wasm32_web_wat_uses_value_store_int_runtime_helper() {
    let program = parse_program(
        r#"<?php
function show(array $items): int {
    return array_sum($items);
}
$a = [1, 2, 3];
echo show($a);
"#,
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT output was not UTF-8");

    assert!(wat.contains("(func $__rt_value_store_int"));
    assert!(wat.contains("call $__rt_value_store_int"));
}

