#[test]
fn test_wasm32_web_wat_retains_array_payload_on_value_store() {
    let program = parse_program(
        r#"<?php
function show(mixed $value): void {
    echo gettype($value);
}
$a = [1, 2];
show($a);
"#,
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT output was not UTF-8");
    let helper_start = wat
        .find("(func $__rt_value_store_array")
        .expect("missing array value-store helper");
    let helper_end = wat[helper_start..]
        .find("(func $__rt_value_store_null")
        .map(|offset| helper_start + offset)
        .expect("missing next value-store helper");
    let helper = &wat[helper_start..helper_end];

    assert!(helper.contains("call $__rt_incref"));
}

