#[test]
fn test_wasm32_web_e2e_matches_php_array_rand_partial_count_associative_keys() {
    assert_wasm_matches_php(
        r#"<?php
$string_keys = array_rand(["left" => 1, "right" => 2, "up" => 3, "down" => 4], 2);
echo count($string_keys) . ":" . gettype($string_keys[0]) . ":";
echo (($string_keys[0] === "left" || $string_keys[0] === "right" || $string_keys[0] === "up" || $string_keys[0] === "down") ? "known" : "bad") . ":";
echo (($string_keys[0] !== $string_keys[1]) ? "unique" : "duplicate") . "\n";
$int_keys = array_rand([3 => "a", 5 => "b", 9 => "c", 11 => "d"], 2);
echo count($int_keys) . ":" . gettype($int_keys[0]) . ":";
echo (($int_keys[0] === 3 || $int_keys[0] === 5 || $int_keys[0] === 9 || $int_keys[0] === 11) ? "known" : "bad") . ":";
echo (($int_keys[0] !== $int_keys[1]) ? "unique" : "duplicate") . "\n";
$mixed_source = [1 => "a", "b" => "c", 3 => "d", "e" => "f"];
$mixed_keys = array_rand($mixed_source, 2);
echo count($mixed_keys) . ":";
echo (is_int($mixed_keys[0]) || is_string($mixed_keys[0])) ? "typed" : "bad";
echo ":";
echo (is_int($mixed_keys[1]) || is_string($mixed_keys[1])) ? "typed" : "bad";
"#,
    );
}

