#[test]
fn test_wasm32_web_wat_array_rand_uses_host_random() {
    let program = parse_program("<?php $a = [1, 2, 3]; echo array_rand($a);");
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT should be UTF-8");
    assert!(wat.contains("(import \"elephc\" \"randomU32\""));
    assert!(wat.contains("call $host_random_u32"));
}

#[test]
fn test_wasm32_web_wat_array_rand_partial_mixed_assoc_compiles() {
    let program = parse_program(
        "<?php $keys = array_rand([1 => \"a\", \"b\" => \"c\", 3 => \"d\", \"e\" => \"f\"], 2); echo count($keys);",
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT should be UTF-8");
    assert!(wat.contains("call $__rt_assoc_key_payload_i64"));
    assert!(wat.contains("call $__rt_value_store_string"));
}

