#[test]
fn test_wasm32_web_array_rand_empty_array_is_rejected() {
    for source in [
        "<?php echo array_rand([]);",
    ] {
        let program = parse_program(source);
        let err = generate(&program, WasmOutputFormat::Wat)
            .expect_err("unsupported array_rand shape must not silently compile");
        assert!(err.message.contains("array_rand()"));
    }
}

