#[test]
fn test_wasm32_web_wat_dynamic_value_array_write_checks_bounds() {
    let program = parse_program(
        r#"<?php
function runtime_index(int $value): int {
    return $value;
}
$a = [1, "two", null];
$i = runtime_index(1);
$a[$i] = "changed";
echo $a[$i];
"#,
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT output was not UTF-8");

    assert!(wat.contains("dynamic_value_sparse_key"));
    assert!(wat.contains("call $__rt_alloc_assoc_entries"));
    assert!(wat.contains("call $__rt_assoc_store_int_key"));
    assert!(wat.contains("call $__rt_value_copy"));
}

