#[test]
fn test_wasm32_web_e2e_matches_php_mixed_pop_shift_strict_literal_comparisons() {
    assert_wasm_matches_php(
        r#"<?php
$a = [1, "two", true, null, 2.5];
$float = array_pop($a);
$last = array_pop($a);
$bool = array_pop($a);
$str = array_pop($a);
$int = array_pop($a);
echo ($last === null ? "null" : "bad") . ":" . ($last !== null ? "bad" : "same") . "\n";
echo ($bool === true ? "true" : "bad") . ":" . ($bool !== false ? "notfalse" : "bad") . "\n";
echo ($str === "two" ? "str" : "bad") . ":" . ($str !== "no" ? "notno" : "bad") . "\n";
echo ($int === 1 ? "int" : "bad") . ":" . ($int !== 2 ? "not2" : "bad") . "\n";
echo ($float === 2.5 ? "float" : "bad") . ":" . ($float !== 3.5 ? "not35" : "bad") . "\n";
"#,
    );
}

