#[test]
fn test_wasm32_web_e2e_matches_php_unknown_mixed_array_pop_assignment() {
    assert_wasm_matches_php(
        r#"<?php
function id_mixed(mixed $value): mixed {
    return $value;
}
function show_unknown_pop(mixed $value) {
    echo gettype($value);
    echo ":";
    echo empty($value) ? "empty" : "full";
    echo "\n";
}
function return_unknown_pop(mixed $items): mixed {
    return array_pop($items);
}
$items = id_mixed([1, "two", false]);
$alias = $items;
echo array_pop($items) . ":" . count($items) . ":" . count($alias) . "\n";
$last = id_mixed(null);
$last = array_pop($items);
echo gettype($last) . ":" . (empty($last) ? "empty" : "full") . ":" . count($items) . ":" . count($alias) . "\n";
$last = array_pop($items);
echo strlen($last) . ":" . ord($last) . ":" . count($items) . "\n";
$old = id_mixed(null);
$old = $alias[1];
echo strlen($old) . ":" . ord($old) . "\n";
$assoc = id_mixed(["name" => "Ada", 4 => "four"]);
$assoc_alias = $assoc;
echo array_pop($assoc) . ":" . count($assoc) . ":" . count($assoc_alias) . "\n";
$assoc_last = id_mixed(null);
$assoc_last = array_pop($assoc);
echo strlen($assoc_last) . ":" . ord($assoc_last) . ":" . count($assoc) . ":" . count($assoc_alias) . "\n";
$assoc_old = id_mixed(null);
$assoc_old = $assoc_alias[4];
echo strlen($assoc_old) . ":" . ord($assoc_old) . "\n";
$empty = id_mixed([]);
echo array_pop($empty) . ":" . count($empty) . "\n";
$nothing = id_mixed(null);
$nothing = array_pop($empty);
echo gettype($nothing) . ":" . (empty($nothing) ? "empty" : "full") . ":" . count($empty) . "\n";
$drop = id_mixed(["x", "y", "z"]);
array_pop($drop);
$drop_kept = id_mixed(null);
$drop_kept = $drop[1];
echo count($drop) . ":" . strlen($drop_kept) . "\n";
$assoc_drop = id_mixed(["a" => "x", "b" => "y"]);
array_pop($assoc_drop);
$assoc_drop_kept = id_mixed(null);
$assoc_drop_kept = $assoc_drop["a"];
echo count($assoc_drop) . ":" . strlen($assoc_drop_kept) . "\n";
$arg = id_mixed(["left", "right"]);
show_unknown_pop(array_pop($arg));
echo count($arg) . "\n";
$named = id_mixed(["left", false]);
show_unknown_pop(value: array_pop($named));
echo count($named) . "\n";
$returned = return_unknown_pop(id_mixed(["x", "tail"]));
echo gettype($returned) . ":" . strlen($returned) . "\n";
"#,
    );
}

