#[test]
fn test_wasm32_web_wat_uses_value_copy_index_or_null_runtime_helper() {
    let program = parse_program(
        r#"<?php
function pick(array $values, int $index): mixed {
    return $values[$index];
}
echo gettype(pick([10, null], 1));
"#,
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT output was not UTF-8");

    assert!(wat.contains("(func $__rt_value_copy_index_or_null"));
    assert!(wat.contains("call $__rt_value_copy_index_or_null"));
}

