#[test]
fn test_wasm32_web_e2e_matches_php_known_mixed_numeric_arithmetic() {
    assert_wasm_matches_php(
        r#"<?php
function show_math(mixed $slot): void {
    $slot = 7;
    echo ($slot + 3) . ":" . ($slot - 2) . ":" . ($slot * 4) . "\n";
    $slot = 2.5;
    echo ($slot + 1) . ":" . ($slot - 0.5) . ":" . ($slot * 2) . "\n";
    $slot = true;
    echo ($slot + 4) . ":" . ($slot * 5) . "\n";
    $slot = null;
    echo ($slot + 4) . ":" . ($slot * 5) . "\n";
    $other = 1.5;
    echo ($slot + $other) . "\n";
    $slot = 7;
    echo ($slot / 2) . "\n";
    $slot = 2.5;
    echo ($slot / 2) . "\n";
    $slot = true;
    echo ($slot / 2) . "\n";
    $slot = null;
    echo ($slot / 2) . "\n";
    $slot = 7.9;
    echo ($slot % 3) . "\n";
    $slot = true;
    echo ($slot % 2) . "\n";
    $slot = null;
    echo ($slot % 2) . "\n";
    $slot = 6;
    echo ($slot & 3) . "\n";
    $slot = 5.8;
    echo ($slot | 2) . "\n";
    $slot = true;
    echo ($slot ^ 3) . "\n";
    $slot = null;
    echo ($slot | 2) . "\n";
    $slot = 7;
    echo (-$slot) . "\n";
    $slot = 2.5;
    echo (-$slot) . "\n";
    $slot = true;
    echo (-$slot) . "\n";
    $slot = null;
    echo (-$slot) . "\n";
    $slot = 8.9;
    echo ($slot << 1) . "\n";
    $slot = true;
    echo ($slot << 2) . "\n";
    $slot = null;
    echo ($slot << 2) . "\n";
    $slot = 8;
    $shift = true;
    echo ($slot >> $shift) . "\n";
    $slot = 5;
    echo (~$slot) . "\n";
    $slot = 5.8;
    echo (~$slot) . "\n";
    $slot = 2;
    echo ($slot ** 3) . "\n";
    $slot = 2.5;
    echo ($slot ** 2) . "\n";
    $slot = true;
    echo ($slot ** 3) . "\n";
    $slot = null;
    echo ($slot ** 2) . "\n";
    $slot = "2.5x";
    echo ($slot + 1) . ":" . ($slot * 2) . ":" . ($slot ** 2) . "\n";
    $slot = "7x";
    echo ($slot & 3) . ":" . ($slot | 8) . ":" . ($slot ^ 1) . ":" . ($slot << 2) . "\n";
}
show_math("start");
"#,
    );
}

