#[test]
fn test_wasm32_web_e2e_matches_php_mixed_string_param_return_numeric_arithmetic() {
    assert_wasm_matches_php(
        r#"<?php
function mixed_string(string $value): mixed {
    return $value;
}
function mixed_string_copy(string $value): mixed {
    $copy = $value;
    return $copy;
}
echo (mixed_string("2.5x") + 1) . ":" . (mixed_string("2.5x") * 2) . "\n";
echo (mixed_string("7x") & 3) . ":" . (mixed_string("7x") | 8) . ":" . (mixed_string("3x") << 2) . "\n";
echo (mixed_string_copy("4x") + 1) . "\n";
"#,
    );
}

