#[test]
fn test_wasm32_web_e2e_matches_php_known_mixed_numeric_comparisons() {
    assert_wasm_matches_php(
        r#"<?php
function mark(bool $value): string {
    return $value ? "T" : "F";
}
function show_compare(mixed $slot): void {
    $slot = 7;
    echo mark($slot > 3) . mark($slot <= 7) . mark($slot == 7) . mark($slot != 8) . "\n";
    $slot = 2.5;
    echo mark($slot < 3) . mark($slot >= 2.5) . mark($slot == 2.5) . "\n";
    $slot = null;
    echo mark($slot == 0) . mark($slot < 1) . mark($slot != 1) . "\n";
    $slot = true;
    echo mark($slot == 2) . mark($slot < 2) . mark($slot > 0) . "\n";
    $slot = false;
    echo mark($slot == 0) . mark($slot < 1) . mark($slot >= null) . "\n";
    $other = 2.5;
    $slot = 7;
    echo mark($slot > $other) . mark($other < $slot) . "\n";
}
show_compare("start");
"#,
    );
}

