#[test]
fn test_wasm32_web_wat_array_shuffle_uses_host_random() {
    let program = parse_program("<?php $a = [1, 2, 3]; shuffle($a); echo count($a);");
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT should be UTF-8");
    assert!(wat.contains("(import \"elephc\" \"randomU32\""));
    assert!(wat.contains("call $host_random_u32"));
}

