#[test]
fn test_wasm32_web_e2e_matches_php_runtime_normalized_array_pad_lookup_search() {
    assert_wasm_matches_php(
        r#"<?php
$keys = explode(",", "a,2,02,-3,+4");
$values = explode(",", "aye,two,leading,neg,plus");
$map = array_combine($keys, $values);
$right = array_pad($map, 7, "pad");
echo (array_key_exists("a", $right) ? "Y" : "N") . ",";
echo (array_key_exists(2, $right) ? "Y" : "N") . ",";
echo (array_key_exists("02", $right) ? "Y" : "N") . ",";
echo (array_key_exists(3, $right) ? "Y" : "N") . "\n";
echo (in_array("pad", $right, true) ? "Y" : "N") . ",";
echo array_search("pad", $right, true) . ",";
echo gettype(array_search("plus", $right, true)) . ":" . array_search("plus", $right, true) . "\n";
echo array_search("neg", $right, true) . ",";
echo gettype(array_search("neg", $right, true)) . ":" . array_search("neg", $right, true) . "\n";
echo (array_search("neg", $right, true) !== false ? "Y" : "N") . ",";
echo (array_search("missing", $right, true) === false ? "Y" : "N") . "\n";
$left = array_pad($map, -7, "pad");
echo (array_key_exists(0, $left) ? "Y" : "N") . ",";
echo (array_key_exists(1, $left) ? "Y" : "N") . ",";
echo (array_key_exists("a", $left) ? "Y" : "N") . ",";
echo (array_key_exists("+4", $left) ? "Y" : "N") . "\n";
echo (in_array("pad", $left, true) ? "Y" : "N") . ",";
echo array_search("pad", $left, true) . ",";
echo gettype(array_search("plus", $left, true)) . ":" . array_search("plus", $left, true) . "\n";
"#,
    );
}

