#[test]
fn test_wasm32_web_e2e_matches_php_direct_array_combine_runtime_string_key_surfaces() {
    assert_wasm_matches_php(
        r#"<?php
$keys = explode(",", "left,right,left");
$values = explode(",", "one,two,three");
echo count(array_combine($keys, $values)) . ":";
echo array_combine($keys, $values)["left"] . ":";
echo array_combine($keys, $values)["right"] . "\n";
$out_keys = array_keys(array_combine($keys, $values));
$out_values = array_values(array_combine($keys, $values));
echo $out_keys[0] . ":" . $out_keys[1] . "\n";
echo $out_values[0] . ":" . $out_values[1] . "\n";
$int_keys = explode(",", "x,y,x");
echo count(array_combine($int_keys, range(4, 6))) . ":";
echo array_combine($int_keys, range(4, 6))["x"] . ":";
echo array_combine($int_keys, range(4, 6))["y"] . "\n";
"#,
    );
}

