#[test]
fn test_wasm32_web_e2e_matches_php_array_chunk_preserve_keys_true() {
    assert_wasm_matches_php(
        r#"<?php
$items = [4, 5, 6, 7];
foreach (array_chunk([1, 2, 3], 2, true) as $outer => $chunk) {
    foreach ($chunk as $key => $value) {
        echo $outer . ":" . gettype($key) . ":" . $key . ":" . $value . "|";
    }
    echo "\n";
}
$chunks = array_chunk($items, 2, true);
foreach ($chunks as $outer => $chunk) {
    foreach ($chunk as $key => $item) {
        echo $outer . ":" . gettype($key) . ":" . $key . ":" . $item . "|";
    }
    echo "\n";
}
foreach ($chunks[1] as $key => $item) {
    echo "idx:" . gettype($key) . ":" . $key . ":" . $item . "|";
}
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_array_chunk_preserve_keys_scalar_sources() {
    assert_wasm_matches_php(
        r#"<?php
$strings = ["a", "b", "c"];
$string_chunks = array_chunk($strings, 2, true);
foreach ($string_chunks as $outer => $chunk) {
    foreach ($chunk as $key => $item) {
        echo $outer . ":" . gettype($key) . ":" . $key . ":" . $item . "|";
    }
    echo "\n";
}
foreach ($string_chunks[1] as $key => $item) {
    echo "idx:" . gettype($key) . ":" . $key . ":" . $item . "|";
}
echo "\n";

function wasm_chunk_words(): array {
    return ["red", "green", "blue"];
}
$return_chunks = array_chunk(wasm_chunk_words(), 2, true);
foreach ($return_chunks as $outer => $chunk) {
    foreach ($chunk as $key => $item) {
        echo "fn:" . $outer . ":" . gettype($key) . ":" . $key . ":" . $item . "|";
    }
    echo "\n";
}
foreach ($return_chunks[1] as $key => $item) {
    echo "fnidx:" . gettype($key) . ":" . $key . ":" . $item . "|";
}
echo "\n";

function wasm_chunk_assoc(): array {
    return ["first" => "Ada", 4 => "Grace", "last" => "Linus"];
}
$assoc = ["first" => "red", 9 => "green", "last" => "blue"];
$assoc_chunks = array_chunk($assoc, 2, true);
foreach ($assoc_chunks as $outer => $chunk) {
    foreach ($chunk as $key => $item) {
        echo "assoc:" . $outer . ":" . gettype($key) . ":" . $key . ":" . $item . "|";
    }
    echo "\n";
}
foreach ($assoc_chunks[1] as $key => $item) {
    echo "associdx:" . gettype($key) . ":" . $key . ":" . $item . "|";
}
echo "\n";
foreach (array_chunk(["x" => "ex", 3 => "three", "z" => "zed"], 2, true) as $outer => $chunk) {
    foreach ($chunk as $key => $item) {
        echo "directassoc:" . $outer . ":" . gettype($key) . ":" . $key . ":" . $item . "|";
    }
    echo "\n";
}
$return_assoc_chunks = array_chunk(wasm_chunk_assoc(), 2, true);
foreach ($return_assoc_chunks as $outer => $chunk) {
    foreach ($chunk as $key => $item) {
        echo "fnassoc:" . $outer . ":" . gettype($key) . ":" . $key . ":" . $item . "|";
    }
    echo "\n";
}
foreach ($return_assoc_chunks[1] as $key => $item) {
    echo "fnassocidx:" . gettype($key) . ":" . $key . ":" . $item . "|";
}
echo "\n";

"#,
    );
}

