#[test]
fn test_wasm32_web_e2e_matches_php_array_chunk_runtime_size_preserve_mixed_assoc_row_reads() {
    assert_wasm_matches_php(
r#"<?php
function size_value(): int { return 2; }
function bump_row_int(int $value): int { return $value + 2; }
function scale_row_float(float $value): int { return (int)($value * 10); }
function mark_row_string(string $value): string { return $value . "!"; }
function bool_flag(bool $value): int { return $value ? 7 : 3; }
function first_row_int(array $chunks): int { return $chunks[0]["ia"]; }
function first_row_float(array $chunks): float { return $chunks[0]["fd"]; }
function second_row_string(array $chunks): string { return $chunks[1]["sb"]; }
function second_row_bool(array $chunks): bool { return $chunks[1]["bc"]; }
function direct_first_row_int(): int { return array_chunk(array_combine(["ia", "fd", "sb", "bc"], [1, 2.5, "two", true]), size_value(), true)[0]["ia"]; }
function direct_first_row_float(): float { return array_chunk(array_combine(["ia", "fd", "sb", "bc"], [1, 2.5, "two", true]), size_value(), true)[0]["fd"]; }
function direct_second_row_string(): string { return array_chunk(array_combine(["ia", "fd", "sb", "bc"], [1, 2.5, "two", true]), size_value(), true)[1]["sb"]; }
function direct_second_row_bool(): bool { return array_chunk(array_combine(["ia", "fd", "sb", "bc"], [1, 2.5, "two", true]), size_value(), true)[1]["bc"]; }
$chunks = array_chunk(array_combine(["ia", "fd", "sb", "bc"], [1, 2.5, "two", true]), size_value(), true);
echo $chunks[0]["ia"] . ":" . ((int)($chunks[0]["fd"] * 10)) . ":" . $chunks[1]["sb"] . ":" . $chunks[1]["bc"] . "\n";
$a = $chunks[0]["ia"];
$b = $chunks[0]["fd"];
$c = $chunks[1]["sb"];
$d = $chunks[1]["bc"];
echo gettype($a) . ":" . gettype($b) . ":" . gettype($c) . ":" . gettype($d) . "\n";
echo $a . ":" . ((int)($b * 10)) . ":" . $c . ":" . ($d ? 1 : 0) . "\n";
echo ($chunks[0]["ia"] + 4) . ":" . strlen($chunks[1]["sb"]) . ":" . (($chunks[1]["bc"] == true) ? 1 : 0) . "\n";
echo bump_row_int($chunks[0]["ia"]) . ":" . scale_row_float($chunks[0]["fd"]) . ":" . mark_row_string($chunks[1]["sb"]) . ":" . bool_flag($chunks[1]["bc"]) . "\n";
echo first_row_int($chunks) . ":" . ((int)(first_row_float($chunks) * 10)) . ":" . second_row_string($chunks) . ":" . (second_row_bool($chunks) ? 1 : 0) . "\n";
echo direct_first_row_int() . ":" . ((int)(direct_first_row_float() * 10)) . ":" . direct_second_row_string() . ":" . (direct_second_row_bool() ? 1 : 0) . "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_array_chunk_runtime_size_preserve_mixed_assoc_row_transforms() {
    assert_wasm_matches_php(
r#"<?php
function size_value(): int { return 2; }
$chunks = array_chunk(array_combine(["ia", "fd", "sb", "bc"], [1, 2.5, "two", true]), size_value(), true);
$first_values = array_values($chunks[0]);
$first_keys = array_keys($chunks[0]);
$second_values = array_values($chunks[1]);
$second_keys = array_keys($chunks[1]);
echo "v0:" . gettype($first_values[0]) . ":" . $first_values[0] . ":" . gettype($first_values[1]) . ":" . ((int)($first_values[1] * 10)) . "\n";
echo "k0:" . $first_keys[0] . ":" . $first_keys[1] . "\n";
echo "v1:" . gettype($second_values[0]) . ":" . $second_values[0] . ":" . gettype($second_values[1]) . ":" . ($second_values[1] ? 1 : 0) . "\n";
echo "k1:" . $second_keys[0] . ":" . $second_keys[1] . "\n";
$filtered = array_filter($chunks[0]);
foreach ($filtered as $filteredKey => $filteredValue) {
    echo "f:" . $filteredKey . ":" . gettype($filteredValue) . ":" . $filteredValue . "|";
}
echo "\n";
$reversed = array_reverse($chunks[1], true);
$reversed_keys = array_keys($reversed);
$reversed_values = array_values($reversed);
echo "rk:" . $reversed_keys[0] . ":" . $reversed_keys[1] . "\n";
echo "rv:" . gettype($reversed_values[0]) . ":" . ($reversed_values[0] ? 1 : 0) . ":" . gettype($reversed_values[1]) . ":" . $reversed_values[1] . "\n";
foreach ($reversed as $reversedKey => $reversedValue) {
    echo "r:" . $reversedKey . ":" . gettype($reversedValue) . ":" . $reversedValue . "|";
}
echo "\n";
$sliced = array_slice($chunks[1], 0, 2, true);
$sliced_keys = array_keys($sliced);
$sliced_values = array_values($sliced);
echo "sk:" . $sliced_keys[0] . ":" . $sliced_keys[1] . "\n";
echo "sv:" . gettype($sliced_values[0]) . ":" . $sliced_values[0] . ":" . gettype($sliced_values[1]) . ":" . ($sliced_values[1] ? 1 : 0) . "\n";
foreach ($sliced as $slicedKey => $slicedValue) {
    echo "s:" . $slicedKey . ":" . gettype($slicedValue) . ":" . $slicedValue . "|";
}
echo "\n";
$unique = array_unique($chunks[1]);
$unique_keys = array_keys($unique);
$unique_values = array_values($unique);
echo "uk:" . $unique_keys[0] . ":" . $unique_keys[1] . "\n";
echo "uv:" . gettype($unique_values[0]) . ":" . $unique_values[0] . ":" . gettype($unique_values[1]) . ":" . ($unique_values[1] ? 1 : 0) . "\n";
foreach ($unique as $uniqueKey => $uniqueValue) {
    echo "u:" . $uniqueKey . ":" . gettype($uniqueValue) . ":" . $uniqueValue . "|";
}
echo "\n";
$merged = array_merge($chunks[1], ["tail" => "done"]);
$merged_keys = array_keys($merged);
$merged_values = array_values($merged);
echo "mk:" . $merged_keys[0] . ":" . $merged_keys[1] . ":" . $merged_keys[2] . "\n";
echo "mv:" . gettype($merged_values[0]) . ":" . $merged_values[0] . ":" . gettype($merged_values[1]) . ":" . ($merged_values[1] ? 1 : 0) . ":" . gettype($merged_values[2]) . ":" . $merged_values[2] . "\n";
foreach ($merged as $mergedKey => $mergedValue) {
    echo "m:" . $mergedKey . ":" . gettype($mergedValue) . ":" . $mergedValue . "|";
}
echo "\n";
$padded = array_pad($chunks[1], 4, "pad");
$padded_keys = array_keys($padded);
$padded_values = array_values($padded);
echo "pk:" . $padded_keys[0] . ":" . $padded_keys[1] . ":" . $padded_keys[2] . ":" . $padded_keys[3] . "\n";
echo "pv:" . gettype($padded_values[0]) . ":" . $padded_values[0] . ":" . gettype($padded_values[1]) . ":" . ($padded_values[1] ? 1 : 0) . ":" . gettype($padded_values[2]) . ":" . $padded_values[2] . ":" . gettype($padded_values[3]) . ":" . $padded_values[3] . "\n";
foreach ($padded as $paddedKey => $paddedValue) {
    echo "p:" . $paddedKey . ":" . gettype($paddedValue) . ":" . $paddedValue . "|";
}
echo "\n";
$diffed = array_diff($chunks[1], ["two"]);
$diffed_keys = array_keys($diffed);
$diffed_values = array_values($diffed);
echo "dk:" . $diffed_keys[0] . "\n";
echo "dv:" . gettype($diffed_values[0]) . ":" . ($diffed_values[0] ? 1 : 0) . "\n";
foreach ($diffed as $diffedKey => $diffedValue) {
    echo "d:" . $diffedKey . ":" . gettype($diffedValue) . ":" . ($diffedValue ? 1 : 0) . "|";
}
echo "\n";
$intersected = array_intersect($chunks[1], [true]);
$intersected_keys = array_keys($intersected);
$intersected_values = array_values($intersected);
echo "ik:" . $intersected_keys[0] . "\n";
echo "iv:" . gettype($intersected_values[0]) . ":" . ($intersected_values[0] ? 1 : 0) . "\n";
foreach ($intersected as $intersectedKey => $intersectedValue) {
    echo "i:" . $intersectedKey . ":" . gettype($intersectedValue) . ":" . ($intersectedValue ? 1 : 0) . "|";
}
echo "\n";
$later_filtered = array_filter($chunks[1]);
$later_filtered_keys = array_keys($later_filtered);
$later_filtered_values = array_values($later_filtered);
echo "lfk:" . $later_filtered_keys[0] . ":" . $later_filtered_keys[1] . "\n";
echo "lfv:" . gettype($later_filtered_values[0]) . ":" . $later_filtered_values[0] . ":" . gettype($later_filtered_values[1]) . ":" . ($later_filtered_values[1] ? 1 : 0) . "\n";
foreach ($later_filtered as $laterFilteredKey => $laterFilteredValue) {
    echo "lf:" . $laterFilteredKey . ":" . gettype($laterFilteredValue) . ":" . $laterFilteredValue . "|";
}
echo "\n";
$row_json = json_encode($chunks[1]);
echo "j:" . $row_json . ":" . strlen($row_json) . "\n";
$row_imploded = implode("|", $chunks[1]);
echo "im:" . $row_imploded . ":" . strlen($row_imploded) . "\n";
echo "io:";
echo implode("|", $chunks[1]);
echo "\n";
echo "num:" . array_sum($chunks[1]) . ":" . array_product($chunks[1]) . "\n";
"#,
    );
}

