#[test]
fn test_wasm32_web_e2e_matches_php_value_array_in_array_predicates() {
    assert_wasm_matches_php(
        r#"<?php
const NEEDLE = "two";
$a = [1, "two", true, false, null, 2.5];
echo (in_array(NEEDLE, $a, true) ? 1 : 0) . ":" . (in_array("ab" . "sent", $a, true) ? 1 : 0) . "\n";
$strict = true;
$bool = true;
echo (in_array($bool, $a, true) ? 1 : 0) . ":" . (in_array(false, $a, true) ? 1 : 0) . "\n";
echo (in_array(1, $a, $strict) ? 1 : 0) . ":" . (in_array(9, $a, $strict) ? 1 : 0) . "\n";
$float = 2.5;
echo (in_array($float, $a, true) ? 1 : 0) . ":" . (in_array(3.5, $a, true) ? 1 : 0) . "\n";
$mixed = [1, "two"];
echo (in_array(null, $a, true) ? 1 : 0) . ":" . (in_array(null, $mixed, true) ? 1 : 0) . "\n";
echo (in_array(null, [1, "two"], true) ? 1 : 0) . ":";
echo (in_array("two", [1, "two"], true) ? 1 : 0) . ":";
echo (in_array(2.5, [1, 2.5], true) ? 1 : 0) . "\n";
"#,
    );
}

