#[test]
fn test_wasm32_web_e2e_matches_php_value_array_search_strict_scalars() {
    assert_wasm_matches_php(
        r#"<?php
const SEARCH_TEXT = "two";
$a = [1, "two", true, false, null, 2.5];
$needle = 1;
$bool_needle = true;
echo array_search($needle, $a, true) . ":" . array_search(SEARCH_TEXT, $a, true) . ":" . array_search($bool_needle, $a, true) . "\n";
$strict = true;
$false = array_search(false, $a, true);
$null = array_search(null, $a, true);
$float_needle = 2.5;
$float = array_search($float_needle, $a, $strict);
$missing = array_search("missing", $a, true);
echo ($false === false ? "bad" : $false) . ":" . ($null === false ? "bad" : $null) . ":" . ($missing === false ? "missing" : "bad") . "\n";
echo ($float === false ? "bad" : $float) . ":" . (array_search(3.5, $a, true) === false ? "missing-float" : "bad") . "\n";
echo array_search("t" . "wo", $a, true) . ":" . (array_search("ab" . "sent", $a, true) === false ? "missing-text" : "bad") . "\n";
echo array_search(null, [1, "two", null], true) . ":";
echo array_search("two", [1, "two", null], true) . ":";
echo array_search(2.5, [1, 2.5, "2.5"], true) . "\n";
"#,
    );
}

