#[test]
fn test_wasm32_web_e2e_matches_php_associative_array_key_exists() {
    assert_wasm_matches_php(
        r#"<?php
$a = ["name" => "Ada", 2 => null, "nested" => [1, 2]];
echo (array_key_exists("name", $a) ? 1 : 0) . ":";
echo (array_key_exists(2, $a) ? 1 : 0) . ":";
echo (array_key_exists("nested", $a) ? 1 : 0) . ":";
echo (array_key_exists("missing", $a) ? 1 : 0) . ":";
echo (array_key_exists(3, $a) ? 1 : 0) . "\n";
$name = "name";
$missing = "missing";
$two = 2;
$three = 3;
echo (array_key_exists($name, $a) ? 1 : 0) . ":";
echo (array_key_exists($missing, $a) ? 1 : 0) . ":";
echo (array_key_exists($two, $a) ? 1 : 0) . ":";
echo (array_key_exists($three, $a) ? 1 : 0) . "\n";
$prefix = "na";
$suffix = "me";
echo (array_key_exists($prefix . $suffix, $a) ? 1 : 0) . ":";
echo (array_key_exists($prefix . "da", $a) ? 1 : 0) . "\n";
$base = 1;
echo (array_key_exists($base + 1, $a) ? 1 : 0) . ":";
echo (array_key_exists($base + 2, $a) ? 1 : 0) . "\n";
"#,
    );
}

