#[test]
fn test_wasm32_web_wat_uses_mixed_tag_runtime_helpers() {
    let program = parse_program(
        r#"<?php
function choose(bool $flag): mixed {
    if ($flag) {
        return 42;
    }
    return "x";
}
function show_payloads(mixed $slot): void {
    $slot = 7;
    echo intval($slot);
    $slot = 2.5;
    echo floatval($slot);
    $slot = "abc";
    echo strlen($slot);
    echo ($slot === "abc" ? 1 : 0);
}
$value = choose(true);
echo gettype($value) . ":" . (is_int($value) ? "yes" : "no") . ":";
show_payloads("start");
"#,
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT output was not UTF-8");

    assert!(wat.contains("(func $__rt_mixed_tag (param $cell i32) (result i32)"));
    assert!(wat.contains("(func $__rt_mixed_tag_equals"));
    assert!(wat.contains("(func $__rt_mixed_payload_i32"));
    assert!(wat.contains("(func $__rt_mixed_payload_i64"));
    assert!(wat.contains("(func $__rt_mixed_payload_f64"));
    assert!(wat.contains("call $__rt_mixed_tag"));
    assert!(wat.contains("call $__rt_mixed_tag_equals"));
    assert!(wat.contains("call $__rt_mixed_payload_i32"));
    assert!(wat.contains("call $__rt_mixed_payload_i64"));
    assert!(wat.contains("call $__rt_mixed_payload_f64"));
}

