#[test]
fn test_wasm32_web_wat_uses_value_tag_equals_runtime_helper() {
    let program = parse_program(
        r#"<?php
$a = [1, "1", true, false, null, "", 0, "0", 7];
$i = array_intersect($a, ["1"], [true]);
echo count($i);
"#,
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT output was not UTF-8");

    assert!(wat.contains("(func $__rt_value_tag_equals"));
    assert!(wat.contains("call $__rt_value_tag_equals"));
}

