#[test]
fn test_wasm32_web_wat_uses_value_cell_payload_runtime_helpers() {
    let program = parse_program(
        r#"<?php
function keep(float $value): bool {
    return $value > 1.0;
}
function keep_bool(bool $value): bool {
    return $value;
}
$a = ["a" => "1.5", "b" => "0.5"];
$b = array_filter($a, "keep");
$c = ["a" => 0.5, "b" => 2.5];
$d = array_filter($c, "keep");
$e = ["a" => true, "b" => false];
$f = array_filter($e, "keep_bool");
echo count($b) . count($d) . count($f);
"#,
    );
    let bytes = generate(&program, WasmOutputFormat::Wat).expect("WAT generation failed");
    let wat = String::from_utf8(bytes).expect("WAT output was not UTF-8");

    assert!(wat.contains("(func $__rt_value_cell_payload_i32"));
    assert!(wat.contains("(func $__rt_value_cell_payload_i64"));
    assert!(wat.contains("(func $__rt_value_cell_payload_f64"));
    assert!(wat.contains("call $__rt_value_cell_payload_i32"));
    assert!(wat.contains("call $__rt_value_cell_payload_i64"));
    assert!(wat.contains("call $__rt_value_cell_payload_f64"));
}

