#[test]
fn test_wasm32_web_e2e_matches_php_direct_assoc_array_value_set_ops() {
    assert_wasm_matches_php(
        r#"<?php
function id_mixed(mixed $value): mixed {
    return $value;
}
$dk = id_mixed(null);
$dv = id_mixed(null);
foreach (array_diff(["a" => "red", 4 => true, "n" => null, "z" => "blue"], ["blue", false]) as $dk => $dv) {
    echo $dk . ":" . gettype($dv) . ":" . $dv . ";";
}
echo "\n";
$ik = id_mixed(null);
$iv = id_mixed(null);
foreach (array_intersect(["a" => "red", 4 => true, "n" => null, "z" => "blue"], ["blue", false]) as $ik => $iv) {
    echo $ik . ":" . gettype($iv) . ":" . $iv . ";";
}
echo "\n";
"#,
    );
}

