#[test]
fn test_wasm32_web_e2e_matches_php_array_value_set_ops_function_returns() {
    assert_wasm_matches_php(
        r#"<?php
function make_ints(): array {
    return [4, 7, 4, 9, 11];
}
function make_values(): array {
    return [1, "1", true, false, null, "", 0, "0", 7, "7"];
}
function make_assoc(): array {
    return ["a" => "red", "b" => "blue", "c" => "red"];
}
function id_mixed(mixed $value): mixed {
    return $value;
}
$d = array_diff(make_ints(), [4], [11]);
echo count($d) . ":" . $d[1] . ":" . $d[3] . ":" . $d[0] . "\n";
$i = array_intersect(make_ints(), [4, 7, 12], [4, 11, 7]);
echo count($i) . ":" . $i[0] . ":" . $i[1] . ":" . $i[2] . ":" . $i[3] . "\n";
$drop = [1, 7];
$vd = array_diff(make_values(), $drop);
echo count($vd) . ":" . $vd[3] . ":" . $vd[4] . ":" . $vd[5] . ":" . $vd[6] . ":" . $vd[7] . "\n";
$keep = [1, 7];
$also = [7, 1];
$vi = array_intersect(make_values(), $keep, $also);
echo count($vi) . ":" . $vi[0] . ":" . $vi[1] . ":" . $vi[2] . ":" . $vi[8] . ":" . $vi[9] . "\n";
$ak = id_mixed(null);
$av = id_mixed(null);
foreach (array_diff(make_assoc(), ["blue"]) as $ak => $av) {
    echo $ak . ":" . $av . ";";
}
echo "\n";
$ik = id_mixed(null);
$iv = id_mixed(null);
foreach (array_intersect(make_assoc(), ["blue"]) as $ik => $iv) {
    echo $ik . ":" . $iv . ";";
}
echo "\n";
"#,
    );
}

