#[test]
fn test_wasm32_web_e2e_matches_php_returned_assoc_array_key_sets() {
    assert_wasm_matches_php(
        r#"<?php
function source_assoc(): array {
    return ["a" => 1, "b" => "two", "aa" => true, 3 => null];
}
function drop_assoc(): array {
    return ["b" => 0, 7 => 0];
}
function keep_assoc(): array {
    return ["aa" => 0, 3 => 0, "z" => 0];
}
$d = array_diff_key(source_assoc(), drop_assoc());
echo count($d) . ":" . $d["a"] . ":" . $d["aa"] . ":" . $d[3] . "\n";
$i = array_intersect_key(source_assoc(), ["a" => 0, "aa" => 0, 3 => 0], keep_assoc());
echo count($i) . ":" . $i["aa"] . ":" . $i[3] . ":" . (array_key_exists("a", $i) ? 1 : 0) . "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_assoc_array_key_sets_preserve_scalar_reads() {
    assert_wasm_matches_php(
        r#"<?php
$a = ["a" => 1, "b" => "two", "aa" => true, 3 => null, "f" => 2.5];
$drop = ["b" => 0, 7 => 0];
$d = array_diff_key($a, $drop);
echo count($d) . ":" . gettype($d["a"]) . ":" . gettype($d["aa"]) . ":" . gettype($d[3]) . ":" . gettype($d["f"]) . "\n";
$keep = ["aa" => 0, 3 => 0, "f" => 0];
$also_keep = ["aa" => 0, 3 => 0, "f" => 0, "z" => 0];
$i = array_intersect_key($a, $keep, $also_keep);
echo count($i) . ":" . gettype($i["aa"]) . ":" . gettype($i[3]) . ":" . gettype($i["f"]) . ":" . (array_key_exists("a", $i) ? 1 : 0) . "\n";
"#,
    );
}

