#[test]
fn test_wasm32_web_e2e_matches_php_array_callbacks_direct_first_class_function_ints() {
    assert_wasm_matches_php(
        r#"<?php
function double_fc(int $value): int {
    return $value * 2;
}
function keep_fc(int $value): bool {
    return $value > 1;
}
function add_fc(int $carry, int $value): int {
    return $carry + $value;
}
function show_fc(int $value): int {
    echo $value . ",";
    return 0;
}
function cmp_fc(int $left, int $right): int {
    return $right - $left;
}
$mapped = array_map(double_fc(...), [1, 2]);
$assoc_mapped = array_map(double_fc(...), ["a" => 2, "b" => 3]);
$filtered = array_filter([1, 2, 3], keep_fc(...));
$assoc_filtered = array_filter(["x" => 1, "y" => 2, "z" => 3], keep_fc(...));
echo count($mapped) . ":" . $mapped[0] . ":" . $mapped[1] . "\n";
echo count($assoc_mapped) . ":" . $assoc_mapped["a"] . ":" . $assoc_mapped["b"] . "\n";
echo count($filtered) . "\n";
echo count($assoc_filtered) . ":" . $assoc_filtered["y"] . ":" . $assoc_filtered["z"] . "\n";
echo array_reduce([1, 2, 3], add_fc(...), 10) . "\n";
echo array_reduce(["left" => 2, "right" => 3], add_fc(...), 10) . "\n";
$walked = [4, 5];
$ok = array_walk($walked, show_fc(...));
echo ":" . ($ok ? 1 : 0) . "\n";
$assoc_walked = ["left" => 6, "right" => 7];
$assoc_ok = array_walk($assoc_walked, show_fc(...));
echo ":" . ($assoc_ok ? 1 : 0) . "\n";
$sorted = [2, 1, 3];
$sort_ok = usort($sorted, cmp_fc(...));
echo ($sort_ok ? 1 : 0) . ":" . $sorted[0] . "," . $sorted[1] . "," . $sorted[2] . "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_array_callbacks_callable_variable_ints() {
    assert_wasm_matches_php(
        r#"<?php
function double_var_cb(int $value): int {
    return $value * 2;
}
function keep_var_cb(int $value): bool {
    return $value != 2;
}
function add_var_cb(int $carry, int $value): int {
    return $carry + $value;
}
function show_var_cb(int $value): int {
    echo $value . ",";
    return 0;
}
function cmp_var_cb(int $left, int $right): int {
    return $right - $left;
}
$map_cb = double_var_cb(...);
$map_alias = $map_cb;
$filter_cb = keep_var_cb(...);
$reduce_cb = add_var_cb(...);
$walk_cb = show_var_cb(...);
$sort_cb = cmp_var_cb(...);
$mapped = array_map($map_alias, [1, 2, 3]);
$assoc_mapped = array_map($map_alias, ["a" => 3, "b" => 4]);
$filtered = array_filter([1, 2, 3], $filter_cb);
$assoc_filtered = array_filter(["x" => 1, "y" => 2, "z" => 3], $filter_cb);
echo count($mapped) . ":" . $mapped[0] . ":" . $mapped[2] . "\n";
echo count($assoc_mapped) . ":" . $assoc_mapped["a"] . ":" . $assoc_mapped["b"] . "\n";
echo count($filtered) . "\n";
echo count($assoc_filtered) . ":" . $assoc_filtered["x"] . ":" . $assoc_filtered["z"] . "\n";
echo array_reduce([1, 2, 3], $reduce_cb, 10) . "\n";
echo array_reduce(["a" => 4, "b" => 5], $reduce_cb, 10) . "\n";
$walked = [4, 5];
$walk_ok = array_walk($walked, $walk_cb);
echo ":" . ($walk_ok ? 1 : 0) . "\n";
$assoc_walked = ["a" => 6, "b" => 7];
$assoc_walk_ok = array_walk($assoc_walked, $walk_cb);
echo ":" . ($assoc_walk_ok ? 1 : 0) . "\n";
$sorted = [2, 1, 3];
$sort_alias = $sort_cb;
$sort_ok = usort($sorted, $sort_alias);
echo ($sort_ok ? 1 : 0) . ":" . $sorted[0] . "," . $sorted[1] . "," . $sorted[2] . "\n";
"#,
    );
}

