#[test]
fn test_wasm32_web_e2e_matches_php_array_reduce_direct_instance_method_callable_assoc_bool_float_values() {
    assert_wasm_matches_php(
        r#"<?php
class DirectAssocBoolReduceRunner {
    public bool $invert;

    public function __construct(bool $invert) {
        $this->invert = $invert;
    }

    public function combine(bool $carry, bool $value): bool {
        $next = $carry && $value;
        return $this->invert ? !$next : $next;
    }
}

class DirectAssocFloatReduceRunner {
    public float $weight;

    public function __construct(float $weight) {
        $this->weight = $weight;
    }

    public function add(float $carry, float $value): float {
        return $carry + ($value * $this->weight);
    }
}

$boolRunner = new DirectAssocBoolReduceRunner(false);
$bools = ["left" => true, "right" => false];
$staticBool = array_reduce($bools, $boolRunner->combine(...), true);
echo $staticBool ? "T\n" : "F\n";
$boolKeys = explode(",", "first,second");
$boolValues = [true, true];
$runtimeBools = array_combine($boolKeys, $boolValues);
$runtimeBool = array_reduce($runtimeBools, $boolRunner->combine(...), true);
echo $runtimeBool ? "T\n" : "F\n";

$floatRunner = new DirectAssocFloatReduceRunner(1.5);
$floats = ["low" => 2.0, "high" => 4.0];
echo array_reduce($floats, $floatRunner->add(...), 1.0);
echo "\n";
$floatKeys = explode(",", "small,big");
$floatValues = [1.0, 3.0];
$runtimeFloats = array_combine($floatKeys, $floatValues);
echo array_reduce($runtimeFloats, $floatRunner->add(...), 2.0);
echo "\n";
"#,
    );
}

