#[test]
fn test_wasm32_web_e2e_matches_php_array_walk_direct_instance_method_callable_assoc_string_keys() {
    assert_wasm_matches_php(
        r#"<?php
class DirectAssocWalkRunner {
    public string $prefix;

    public function __construct(string $prefix) {
        $this->prefix = $prefix;
    }

    public function show(string $value, string $key): int {
        echo $this->prefix . $key . "=" . $value . ";";
        return 1;
    }
}

$runner = new DirectAssocWalkRunner("k:");
$static = ["left" => "aa", "right" => "bbb"];
$okStatic = array_walk($static, $runner->show(...));
echo ":" . ($okStatic ? 1 : 0) . "\n";

$keys = explode(",", "first,second");
$values = explode(",", "red,blue");
$runtime = array_combine($keys, $values);
$okRuntime = array_walk($runtime, $runner->show(...));
echo ":" . ($okRuntime ? 1 : 0) . "\n";
"#,
    );
}

