#[test]
fn test_wasm32_web_e2e_matches_php_array_walk_direct_instance_method_callable_assoc_bool_float_values_string_keys() {
    assert_wasm_matches_php(
        r#"<?php
class DirectAssocBoolWalkRunner {
    public string $prefix;

    public function __construct(string $prefix) {
        $this->prefix = $prefix;
    }

    public function show(bool $value, string $key): int {
        echo $this->prefix . $key . "=" . ($value ? "T" : "F") . ";";
        return 1;
    }
}

class DirectAssocFloatWalkRunner {
    public float $scale;

    public function __construct(float $scale) {
        $this->scale = $scale;
    }

    public function show(float $value, string $key): int {
        echo $key . "=";
        echo (int)($value * $this->scale);
        echo ";";
        return 1;
    }
}

$boolRunner = new DirectAssocBoolWalkRunner("b:");
$bools = ["left" => true, "right" => false];
$okBoolStatic = array_walk($bools, $boolRunner->show(...));
echo ":" . ($okBoolStatic ? 1 : 0) . "\n";

$boolKeys = explode(",", "first,second");
$boolValues = [false, true];
$runtimeBools = array_combine($boolKeys, $boolValues);
$okBoolRuntime = array_walk($runtimeBools, $boolRunner->show(...));
echo ":" . ($okBoolRuntime ? 1 : 0) . "\n";

$floatRunner = new DirectAssocFloatWalkRunner(10.0);
$floats = ["low" => 1.2, "high" => 2.5];
$okFloatStatic = array_walk($floats, $floatRunner->show(...));
echo ":" . ($okFloatStatic ? 1 : 0) . "\n";

$floatKeys = explode(",", "small,big");
$floatValues = [3.5, 4.25];
$runtimeFloats = array_combine($floatKeys, $floatValues);
$okFloatRuntime = array_walk($runtimeFloats, $floatRunner->show(...));
echo ":" . ($okFloatRuntime ? 1 : 0) . "\n";
"#,
    );
}

