#[test]
fn test_wasm32_web_e2e_matches_php_usort_direct_instance_method_callable_scalar_values() {
    assert_wasm_matches_php(
        r#"<?php
class DirectStringSortRunner {
    public int $direction;

    public function __construct(int $direction) {
        $this->direction = $direction;
    }

    public function compare(string $left, string $right): int {
        return strcmp($left, $right) * $this->direction;
    }
}

class DirectFloatSortRunner {
    public int $direction;

    public function __construct(int $direction) {
        $this->direction = $direction;
    }

    public function compare(float $left, float $right): int {
        if ($left === $right) {
            return 0;
        }
        return ($left < $right ? -1 : 1) * $this->direction;
    }
}

class DirectBoolSortRunner {
    public bool $trueFirst;

    public function __construct(bool $trueFirst) {
        $this->trueFirst = $trueFirst;
    }

    public function compare(bool $left, bool $right): int {
        if ($left === $right) {
            return 0;
        }
        if ($this->trueFirst) {
            return $left ? -1 : 1;
        }
        return $left ? 1 : -1;
    }
}

$strings = ["b", "d", "a", "c"];
usort($strings, (new DirectStringSortRunner(-1))->compare(...));
echo $strings[0] . "," . $strings[3] . "\n";

$floats = [2.5, 4.5, 1.5, 3.5];
usort($floats, (new DirectFloatSortRunner(-1))->compare(...));
echo $floats[0] . "," . $floats[3] . "\n";

$bools = [true, false, true, false];
usort($bools, (new DirectBoolSortRunner(true))->compare(...));
foreach ($bools as $value) {
    echo $value ? "T" : "F";
}
echo "\n";
"#,
    );
}

