#[test]
fn test_wasm32_web_e2e_matches_php_usort_instance_method_callable_variable_bools() {
    assert_wasm_matches_php(
        r#"<?php
class CallableBoolSortRunner {
    public bool $trueFirst;

    public function __construct(bool $trueFirst) {
        $this->trueFirst = $trueFirst;
    }

    public function compare(bool $left, bool $right): int {
        if ($left === $right) {
            return 0;
        }
        if ($this->trueFirst) {
            if ($left) {
                return -1;
            }
            return 1;
        }
        if ($left) {
            return 1;
        }
        return -1;
    }
}

$runner = new CallableBoolSortRunner(true);
$cb = $runner->compare(...);
$values = [true, false, true, false];
$runner = new CallableBoolSortRunner(false);
$ok = usort($values, $cb);
echo ($ok ? 1 : 0) . ":";
foreach ($values as $value) {
    echo $value ? "T" : "F";
}
echo "\n";
"#,
    );
}

