#[test]
fn test_wasm32_web_e2e_matches_php_uasort_direct_instance_method_callable_scalar_values() {
    assert_wasm_matches_php(
        r#"<?php
class DirectAssocStringSortRunner {
    public int $direction;

    public function __construct(int $direction) {
        $this->direction = $direction;
    }

    public function compare(string $left, string $right): int {
        return strcmp($left, $right) * $this->direction;
    }
}

class DirectAssocFloatSortRunner {
    public int $direction;

    public function __construct(int $direction) {
        $this->direction = $direction;
    }

    public function compare(float $left, float $right): int {
        if ($left === $right) {
            return 0;
        }
        return ($left < $right ? -1 : 1) * $this->direction;
    }
}

class DirectAssocBoolSortRunner {
    public bool $trueFirst;

    public function __construct(bool $trueFirst) {
        $this->trueFirst = $trueFirst;
    }

    public function compare(bool $left, bool $right): int {
        if ($left === $right) {
            return 0;
        }
        if ($this->trueFirst) {
            return $left ? -1 : 1;
        }
        return $left ? 1 : -1;
    }
}

$strings = ["a" => "b", "b" => "d", "c" => "a", "d" => "c"];
uasort($strings, (new DirectAssocStringSortRunner(-1))->compare(...));
echo $strings["a"] . ":" . $strings["d"] . "\n";

$floats = ["a" => 2.5, "b" => 4.5, "c" => 1.5, "d" => 3.5];
uasort($floats, (new DirectAssocFloatSortRunner(-1))->compare(...));
echo $floats["a"] . ":" . $floats["d"] . "\n";

$bools = ["a" => false, "b" => true, "c" => false, "d" => true];
uasort($bools, (new DirectAssocBoolSortRunner(true))->compare(...));
foreach ($bools as $value) {
    echo $value ? "T" : "F";
}
echo "\n";
"#,
    );
}

