#[test]
fn test_wasm32_web_e2e_matches_php_uasort_instance_method_callable_variable_bools() {
    assert_wasm_matches_php(
        r#"<?php
class CallableAssocBoolSortRunner {
    public bool $trueFirst;

    public function __construct(bool $trueFirst) {
        $this->trueFirst = $trueFirst;
    }

    public function compare(bool $left, bool $right): int {
        if ($left === $right) {
            return 0;
        }
        if ($this->trueFirst) {
            if ($left) {
                return -1;
            }
            return 1;
        }
        if ($left) {
            return 1;
        }
        return -1;
    }
}

$runner = new CallableAssocBoolSortRunner(true);
$cb = $runner->compare(...);
$values = ["a" => false, "b" => true, "c" => false, "d" => true];
$runner = new CallableAssocBoolSortRunner(false);
uasort($values, $cb);
echo "1:";
echo count($values) . ":";
foreach ($values as $value) {
    if ($value) {
        echo "T";
    } else {
        echo "F";
    }
}
echo "\n";
"#,
    );
}

