#[test]
fn test_wasm32_web_e2e_matches_php_direct_instance_method_callable_more_scalar_arrays() {
    assert_wasm_matches_php(
        r#"<?php
class DirectStringMapRunner {
    public string $suffix;
    public function __construct(string $suffix) { $this->suffix = $suffix; }
    public function add(string $value): string { return $value . $this->suffix; }
}
class DirectFloatFilterRunner {
    public float $min;
    public function __construct(float $min) { $this->min = $min; }
    public function keep(float $value): bool { return $value > $this->min; }
}
class DirectStringReduceRunner {
    public string $sep;
    public function __construct(string $sep) { $this->sep = $sep; }
    public function join(string $carry, string $value): string { return $carry . $this->sep . $value; }
}
class DirectBoolWalkRunner {
    public string $prefix;
    public function __construct(string $prefix) { $this->prefix = $prefix; }
    public function show(bool $value): bool { echo $this->prefix . ($value ? "T" : "F") . ";"; return true; }
}
class DirectStringSortRunner {
    public int $direction;
    public function __construct(int $direction) { $this->direction = $direction; }
    public function compare(string $left, string $right): int { return strcmp($left, $right) * $this->direction; }
}
class DirectBoolAssocSortRunner {
    public bool $trueFirst;
    public function __construct(bool $trueFirst) { $this->trueFirst = $trueFirst; }
    public function compare(bool $left, bool $right): int {
        if ($left === $right) { return 0; }
        return $this->trueFirst ? ($left ? -1 : 1) : ($left ? 1 : -1);
    }
}
class DirectStringKeySortRunner {
    public int $direction;
    public function __construct(int $direction) { $this->direction = $direction; }
    public function compare(string $left, string $right): int { return strcmp($left, $right) * $this->direction; }
}

$mapper = new DirectStringMapRunner("!");
$mapSource = ["a", "bb"];
$mapped = array_map($mapper->add(...), $mapSource);
echo $mapped[0] . ":" . $mapped[1] . "\n";

$filter = new DirectFloatFilterRunner(2.0);
$filterSource = [1.5, 2.25, 3.5];
$filtered = array_filter($filterSource, $filter->keep(...));
echo count($filtered) . ":" . $filtered[1] . ":" . $filtered[2] . "\n";

$reducer = new DirectStringReduceRunner("-");
$reduceSource = ["a", "bb"];
echo array_reduce($reduceSource, $reducer->join(...), "s") . "\n";

$walker = new DirectBoolWalkRunner("b=");
$walked = [true, false];
$ok = array_walk($walked, $walker->show(...));
echo "\n" . ($ok ? 1 : 0) . ":" . count($walked) . "\n";

$sorter = new DirectStringSortRunner(-1);
$strings = ["b", "d", "a", "c"];
usort($strings, $sorter->compare(...));
echo $strings[0] . ":" . $strings[3] . "\n";

$assocSorter = new DirectBoolAssocSortRunner(true);
$assoc = ["a" => false, "b" => true, "c" => false, "d" => true];
uasort($assoc, $assocSorter->compare(...));
echo count($assoc) . ":";
foreach ($assoc as $value) { echo $value ? "T" : "F"; }
echo "\n";

$keySorter = new DirectStringKeySortRunner(-1);
$keys = ["b" => 2, "d" => 4, "a" => 1, "c" => 3];
uksort($keys, $keySorter->compare(...));
foreach ($keys as $key => $value) { echo $key . "=" . $value . ";"; }
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_direct_instance_method_callable_scalar_matrix() {
    assert_wasm_matches_php(
        r#"<?php
class DirectBoolMapRunner {
    public function invert(bool $value): bool { return !$value; }
}
class DirectFloatMapRunner {
    public float $step;
    public function __construct(float $step) { $this->step = $step; }
    public function add(float $value): float { return $value + $this->step; }
}
class DirectBoolFilterRunner {
    public function keep(bool $value): bool { return $value; }
}
class DirectStringFilterRunner {
    public int $min;
    public function __construct(int $min) { $this->min = $min; }
    public function keep(string $value): bool { return strlen($value) > $this->min; }
}
class DirectFloatReduceRunner {
    public float $mul;
    public function __construct(float $mul) { $this->mul = $mul; }
    public function sum(float $carry, float $value): float { return $carry + ($value * $this->mul); }
}
class DirectBoolReduceRunner {
    public function any(bool $carry, bool $value): bool { return $carry || $value; }
}
class DirectIntWalkRunner {
    public function show(int $value): bool { echo "i=" . $value . ";"; return true; }
}
class DirectFloatWalkRunner {
    public function show(float $value): bool { echo "f=" . $value . ";"; return true; }
}
class DirectStringWalkRunner {
    public function show(string $value): bool { echo "s=" . $value . ";"; return true; }
}
class DirectFloatSortRunner {
    public int $direction;
    public function __construct(int $direction) { $this->direction = $direction; }
    public function compare(float $left, float $right): int {
        if ($left === $right) { return 0; }
        return ($left < $right ? -1 : 1) * $this->direction;
    }
}
class DirectBoolSortRunner {
    public bool $trueFirst;
    public function __construct(bool $trueFirst) { $this->trueFirst = $trueFirst; }
    public function compare(bool $left, bool $right): int {
        if ($left === $right) { return 0; }
        return $this->trueFirst ? ($left ? -1 : 1) : ($left ? 1 : -1);
    }
}
class DirectFloatAssocSortRunner {
    public int $direction;
    public function __construct(int $direction) { $this->direction = $direction; }
    public function compare(float $left, float $right): int {
        if ($left === $right) { return 0; }
        return ($left < $right ? -1 : 1) * $this->direction;
    }
}
class DirectStringAssocSortRunner {
    public int $direction;
    public function __construct(int $direction) { $this->direction = $direction; }
    public function compare(string $left, string $right): int { return strcmp($left, $right) * $this->direction; }
}

$boolMapper = new DirectBoolMapRunner();
$boolMapSource = [true, false];
$boolMapped = array_map($boolMapper->invert(...), $boolMapSource);
echo ($boolMapped[0] ? 1 : 0) . ":" . ($boolMapped[1] ? 1 : 0) . "\n";

$floatMapper = new DirectFloatMapRunner(0.5);
$floatMapSource = [1.25, 2.5];
$floatMapped = array_map($floatMapper->add(...), $floatMapSource);
echo $floatMapped[0] . ":" . $floatMapped[1] . "\n";

$boolFilter = new DirectBoolFilterRunner();
$boolFilterSource = [false, true, false];
$boolFiltered = array_filter($boolFilterSource, $boolFilter->keep(...));
echo count($boolFiltered) . ":" . ($boolFiltered[1] ? 1 : 0) . "\n";

$stringFilter = new DirectStringFilterRunner(1);
$stringFilterSource = ["", "a", "bbb"];
$stringFiltered = array_filter($stringFilterSource, $stringFilter->keep(...));
echo count($stringFiltered) . ":" . $stringFiltered[2] . "\n";

$floatReducer = new DirectFloatReduceRunner(2.0);
$floatReduceSource = [1.5, 2.0];
echo array_reduce($floatReduceSource, $floatReducer->sum(...), 1.0) . "\n";

$boolReducer = new DirectBoolReduceRunner();
$boolReduceSource = [false, true];
echo (array_reduce($boolReduceSource, $boolReducer->any(...), false) ? 1 : 0) . "\n";

$intWalker = new DirectIntWalkRunner();
$intWalked = [4, 5];
echo (array_walk($intWalked, $intWalker->show(...)) ? 1 : 0) . "\n";

$floatWalker = new DirectFloatWalkRunner();
$floatWalked = [1.5, 2.25];
echo (array_walk($floatWalked, $floatWalker->show(...)) ? 1 : 0) . "\n";

$stringWalker = new DirectStringWalkRunner();
$stringWalked = ["aa", "b"];
echo (array_walk($stringWalked, $stringWalker->show(...)) ? 1 : 0) . "\n";

$floatSorter = new DirectFloatSortRunner(-1);
$floats = [1.25, 3.5, 2.0];
usort($floats, $floatSorter->compare(...));
echo $floats[0] . ":" . $floats[2] . "\n";

$boolSorter = new DirectBoolSortRunner(true);
$bools = [false, true, false, true];
usort($bools, $boolSorter->compare(...));
foreach ($bools as $value) { echo $value ? "T" : "F"; }
echo "\n";

$floatAssocSorter = new DirectFloatAssocSortRunner(-1);
$floatAssoc = ["a" => 1.25, "b" => 3.5, "c" => 2.0];
uasort($floatAssoc, $floatAssocSorter->compare(...));
foreach ($floatAssoc as $key => $value) { echo $key . "=" . $value . ";"; }
echo "\n";

$stringAssocSorter = new DirectStringAssocSortRunner(1);
$stringAssoc = ["b" => "bb", "a" => "aa", "c" => "cc"];
uasort($stringAssoc, $stringAssocSorter->compare(...));
foreach ($stringAssoc as $key => $value) { echo $key . "=" . $value . ";"; }
echo "\n";
"#,
    );
}

