#[test]
fn test_wasm32_web_e2e_matches_php_array_callbacks_const_bool_function_callable_names() {
    assert_wasm_matches_php(
        r#"<?php
function choose_map_name(bool $flag): string { return $flag ? "const_bool_map" : "missing_map"; }
function choose_filter_name(bool $flag): string { return $flag ? "const_bool_filter" : "missing_filter"; }
function choose_reduce_name(bool $flag): string { return $flag ? "const_bool_reduce" : "missing_reduce"; }
function choose_walk_name(bool $flag): string { return $flag ? "const_bool_walk" : "missing_walk"; }
function choose_sort_name(bool $flag): string { return $flag ? "const_bool_sort" : "missing_sort"; }
function choose_key_sort_name(bool $flag): string { return $flag ? "const_bool_key_sort" : "missing_key_sort"; }
function const_bool_map(int $value): int { return $value + 2; }
function const_bool_filter(int $value): bool { return $value > 1; }
function const_bool_reduce(int $carry, int $value): int { return $carry + $value; }
function const_bool_walk(int $value): int { echo $value . ","; return 0; }
function const_bool_sort(int $left, int $right): int { return $left - $right; }
function const_bool_key_sort(string $left, string $right): int { return strcmp($left, $right); }
$map_cb = choose_map_name(true);
$filter_cb = choose_filter_name(true);
$reduce_cb = choose_reduce_name(true);
$walk_cb = choose_walk_name(true);
$sort_cb = choose_sort_name(true);
$key_sort_cb = choose_key_sort_name(true);
$mapped = array_map($map_cb, [1, 2]);
$filtered = array_filter([1, 2, 3], $filter_cb);
echo count($mapped) . ":" . $mapped[0] . ":" . $mapped[1] . "\n";
echo count($filtered) . ":" . $filtered[1] . ":" . $filtered[2] . "\n";
echo array_reduce([1, 2, 3], $reduce_cb, 10) . "\n";
$walked = [4, 5];
echo (array_walk($walked, $walk_cb) ? 1 : 0) . "\n";
$sorted = [3, 1, 2];
echo (usort($sorted, $sort_cb) ? 1 : 0) . ":" . $sorted[0] . "," . $sorted[1] . "," . $sorted[2] . "\n";
$assoc_values = ["b" => 2, "a" => 1];
echo (uasort($assoc_values, $sort_cb) ? 1 : 0) . ":";
foreach ($assoc_values as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
$assoc_keys = ["b" => 2, "a" => 1];
echo (uksort($assoc_keys, $key_sort_cb) ? 1 : 0) . ":";
foreach ($assoc_keys as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
"#,
    );
}

