#[test]
fn test_wasm32_web_e2e_matches_php_array_walk_bool_return_callbacks() {
    assert_wasm_matches_php(
        r#"<?php
function seen_walk_int(int $value): bool {
    echo "i" . $value . ",";
    return $value > 0;
}
function seen_walk_float(float $value): bool {
    echo "f" . number_format($value, 1, ".", "") . ",";
    return $value > 0.0;
}
function seen_walk_bool(bool $value): bool {
    echo "b" . ($value ? "T" : "F") . ",";
    return $value;
}
function seen_walk_string(string $value): bool {
    echo "s" . $value . ",";
    return $value != "";
}
function seen_walk_int_key(int $value, int $key): bool {
    echo $key . ":" . $value . ",";
    return true;
}
function seen_walk_float_key(float $value, int $key): bool {
    echo $key . ":f" . number_format($value, 1, ".", "") . ",";
    return $value > 0.0;
}
function seen_walk_float_string_key(float $value, string $key): bool {
    echo $key . ":f" . number_format($value, 1, ".", "") . ",";
    return $value > 0.0;
}
function seen_walk_string_key(string $value, string $key): bool {
    echo $key . ":" . $value . ",";
    return true;
}
$ints = [1, 2];
$floats = [0.5, 1.25];
$numeric_string_floats = ["0.5", "1.25"];
$bools = [false, true];
$strings = ["a", "bb"];
$assoc = ["x" => "a", "y" => "bb"];
$assoc_numeric_string_floats = ["x" => "0.5", "y" => "1.25"];
echo (array_walk($ints, "seen_walk_int") ? 1 : 0) . "\n";
echo (array_walk($floats, seen_walk_float(...)) ? 1 : 0) . "\n";
echo (array_walk($numeric_string_floats, seen_walk_float(...)) ? 1 : 0) . "\n";
echo (array_walk($bools, "seen_walk_bool") ? 1 : 0) . "\n";
echo (array_walk($strings, seen_walk_string(...)) ? 1 : 0) . "\n";
echo (array_walk(array_fill(3, 2, 7), "seen_walk_int_key") ? 1 : 0) . "\n";
echo (array_walk(array_fill(3, 2, "2.5"), "seen_walk_float_key") ? 1 : 0) . "\n";
echo (array_walk($numeric_string_floats, "seen_walk_float_key") ? 1 : 0) . "\n";
echo (array_walk($assoc, seen_walk_string_key(...)) ? 1 : 0) . "\n";
echo (array_walk($assoc_numeric_string_floats, seen_walk_float_string_key(...)) ? 1 : 0) . "\n";
"#,
    );
}

