#[test]
fn test_wasm32_web_e2e_matches_php_usort_static_method_callable_ternaries() {
    assert_wasm_matches_php(
        r#"<?php
class UsortStaticTernaryPicker {
    public static function pick(bool $flag): bool { echo $flag ? "left\n" : "right\n"; return $flag; }
}
class UsortStaticTernaryLeft {
    public static function ints(int $left, int $right): int { if ($left == $right) { return 0; } if ($left < $right) { return -1; } return 1; }
    public static function floats(float $left, float $right): int { if ($left == $right) { return 0; } if ($left < $right) { return -1; } return 1; }
    public static function strings(string $left, string $right): int { return strcmp($left, $right); }
    public static function bools(bool $left, bool $right): int { if ($left === $right) { return 0; } if (!$left && $right) { return -1; } return 1; }
}
class UsortStaticTernaryRight {
    public static function ints(int $left, int $right): int { if ($left == $right) { return 0; } if ($left < $right) { return 1; } return -1; }
    public static function floats(float $left, float $right): int { if ($left == $right) { return 0; } if ($left < $right) { return 1; } return -1; }
    public static function strings(string $left, string $right): int { return strcmp($right, $left); }
    public static function bools(bool $left, bool $right): int { if ($left === $right) { return 0; } if ($left && !$right) { return -1; } return 1; }
}
$ints = [3, 1, 2];
$ok1 = usort($ints, UsortStaticTernaryPicker::pick(true) ? UsortStaticTernaryLeft::ints(...) : UsortStaticTernaryRight::ints(...));
echo ($ok1 ? 1 : 0) . ":" . implode(",", $ints) . "\n";
$floats = [3.5, 1.25, 2.75];
$ok2 = usort($floats, UsortStaticTernaryPicker::pick(false) ? UsortStaticTernaryLeft::floats(...) : UsortStaticTernaryRight::floats(...));
echo ($ok2 ? 1 : 0) . ":" . implode(",", $floats) . "\n";
$strings = ["pear", "apple", "banana"];
$ok3 = usort($strings, UsortStaticTernaryPicker::pick(true) ? UsortStaticTernaryLeft::strings(...) : UsortStaticTernaryRight::strings(...));
echo ($ok3 ? 1 : 0) . ":" . implode(",", $strings) . "\n";
$bools = [false, true, false];
$ok4 = usort($bools, UsortStaticTernaryPicker::pick(false) ? UsortStaticTernaryLeft::bools(...) : UsortStaticTernaryRight::bools(...));
echo ($ok4 ? 1 : 0) . ":";
foreach ($bools as $value) { echo $value ? "T" : "F"; }
echo "\n";
"#,
    );
}

