#[test]
fn test_wasm32_web_e2e_matches_php_uasort_static_method_callable_ternaries() {
    assert_wasm_matches_php(
        r#"<?php
class UasortStaticTernaryPicker {
    public static function pick(bool $flag): bool { echo $flag ? "left\n" : "right\n"; return $flag; }
}
class UasortStaticTernaryLeft {
    public static function ints(int $left, int $right): int { if ($left == $right) { return 0; } if ($left < $right) { return -1; } return 1; }
    public static function floats(float $left, float $right): int { if ($left == $right) { return 0; } if ($left < $right) { return -1; } return 1; }
    public static function strings(string $left, string $right): int { return strcmp($left, $right); }
    public static function bools(bool $left, bool $right): int { if ($left === $right) { return 0; } if (!$left && $right) { return -1; } return 1; }
}
class UasortStaticTernaryRight {
    public static function ints(int $left, int $right): int { if ($left == $right) { return 0; } if ($left < $right) { return 1; } return -1; }
    public static function floats(float $left, float $right): int { if ($left == $right) { return 0; } if ($left < $right) { return 1; } return -1; }
    public static function strings(string $left, string $right): int { return strcmp($right, $left); }
    public static function bools(bool $left, bool $right): int { if ($left === $right) { return 0; } if ($left && !$right) { return -1; } return 1; }
}
$ints = ["c" => 3, "a" => 1, "b" => 2];
$ok1 = uasort($ints, UasortStaticTernaryPicker::pick(true) ? UasortStaticTernaryLeft::ints(...) : UasortStaticTernaryRight::ints(...));
echo ($ok1 ? 1 : 0) . ":" . implode(",", $ints) . "\n";
$floats = ["c" => 3.5, "a" => 1.25, "b" => 2.75];
$ok2 = uasort($floats, UasortStaticTernaryPicker::pick(false) ? UasortStaticTernaryLeft::floats(...) : UasortStaticTernaryRight::floats(...));
echo ($ok2 ? 1 : 0) . ":" . implode(",", $floats) . "\n";
$strings = ["p" => "pear", "a" => "apple", "b" => "banana"];
$ok3 = uasort($strings, UasortStaticTernaryPicker::pick(true) ? UasortStaticTernaryLeft::strings(...) : UasortStaticTernaryRight::strings(...));
echo ($ok3 ? 1 : 0) . ":" . implode(",", $strings) . "\n";
$bools = ["f1" => false, "t" => true, "f2" => false];
$ok4 = uasort($bools, UasortStaticTernaryPicker::pick(false) ? UasortStaticTernaryLeft::bools(...) : UasortStaticTernaryRight::bools(...));
echo ($ok4 ? 1 : 0) . ":";
foreach ($bools as $value) { echo $value ? "T" : "F"; }
echo "\n";
"#,
    );
}

