#[test]
fn test_wasm32_web_e2e_matches_php_array_map_strlen_builtin_callback() {
    assert_wasm_matches_php(
        r#"<?php
$literal = array_map(strlen(...), ["a", "", "bc"]);
echo count($literal) . ":" . $literal[0] . ":" . $literal[1] . ":" . $literal[2] . "\n";
$literal_ints = array_map(strlen(...), [0, 12, -300]);
echo count($literal_ints) . ":" . $literal_ints[0] . ":" . $literal_ints[1] . ":" . $literal_ints[2] . "\n";
$literal_bools = array_map(strlen(...), [false, true, false]);
echo count($literal_bools) . ":" . $literal_bools[0] . ":" . $literal_bools[1] . ":" . $literal_bools[2] . "\n";
$literal_floats = array_map(strlen(...), [0.0, 1.25, -0.5]);
echo count($literal_floats) . ":" . $literal_floats[0] . ":" . $literal_floats[1] . ":" . $literal_floats[2] . "\n";
$literal_nulls = array_map(strlen(...), [null, null]);
echo count($literal_nulls) . ":" . $literal_nulls[0] . ":" . $literal_nulls[1] . "\n";
$source = ["web", "", "php"];
$alias = strlen(...);
$assigned = array_map($alias, $source);
echo count($assigned) . ":" . $assigned[0] . ":" . $assigned[1] . ":" . $assigned[2] . "\n";
$int_source = [0, 5, -70];
$assigned_ints = array_map($alias, $int_source);
echo count($assigned_ints) . ":" . $assigned_ints[0] . ":" . $assigned_ints[1] . ":" . $assigned_ints[2] . "\n";
$bool_source = [true, false, true];
$assigned_bools = array_map(strlen(...), $bool_source);
echo count($assigned_bools) . ":" . $assigned_bools[0] . ":" . $assigned_bools[1] . ":" . $assigned_bools[2] . "\n";
$float_source = [0.0, 2.5];
$assigned_floats = array_map(strlen(...), $float_source);
echo count($assigned_floats) . ":" . $assigned_floats[0] . ":" . $assigned_floats[1] . "\n";
$null_source = [null, null];
$assigned_nulls = array_map(strlen(...), $null_source);
echo count($assigned_nulls) . ":" . $assigned_nulls[0] . ":" . $assigned_nulls[1] . "\n";
$runtime = array_map(strlen(...), explode(",", "one,,two"));
echo count($runtime) . ":" . $runtime[0] . ":" . $runtime[1] . ":" . $runtime[2] . "\n";
$runtime_ints = array_map(strlen(...), range(0, 2));
echo count($runtime_ints) . ":" . $runtime_ints[0] . ":" . $runtime_ints[1] . ":" . $runtime_ints[2] . "\n";
$runtime_bools = array_map(strlen(...), array_fill(0, 2, true));
echo count($runtime_bools) . ":" . $runtime_bools[0] . ":" . $runtime_bools[1] . "\n";
$runtime_floats = array_map(strlen(...), array_fill(0, 2, 0.0));
echo count($runtime_floats) . ":" . $runtime_floats[0] . ":" . $runtime_floats[1] . "\n";
$runtime_nulls = array_map(strlen(...), array_fill(0, 2, null));
echo count($runtime_nulls) . ":" . $runtime_nulls[0] . ":" . $runtime_nulls[1] . "\n";
$assoc = array_map(strlen(...), ["x" => "yes", "empty" => "", "z" => "zed"]);
echo count($assoc) . ":" . $assoc["x"] . ":" . $assoc["empty"] . ":" . $assoc["z"] . "\n";
$assoc_scalars = array_map(strlen(...), ["zero" => 0, "one" => 1, "f" => false, "t" => true, "n" => null, "flt" => 0.0]);
echo count($assoc_scalars) . ":" . $assoc_scalars["zero"] . ":" . $assoc_scalars["one"] . ":" . $assoc_scalars["f"] . ":" . $assoc_scalars["t"] . ":" . $assoc_scalars["n"] . ":" . $assoc_scalars["flt"] . "\n";
$assoc_source = ["zero" => 0, "one" => 1, "f" => false, "t" => true, "n" => null, "flt" => 2.5];
$assigned_assoc_scalars = array_map(strlen(...), $assoc_source);
echo count($assigned_assoc_scalars) . ":" . $assigned_assoc_scalars["zero"] . ":" . $assigned_assoc_scalars["one"] . ":" . $assigned_assoc_scalars["f"] . ":" . $assigned_assoc_scalars["t"] . ":" . $assigned_assoc_scalars["n"] . ":" . $assigned_assoc_scalars["flt"] . "\n";
$runtime_assoc_strings = array_map(strlen(...), array_combine(explode(",", "left,right,empty"), explode(",", "aa,bb,")));
echo count($runtime_assoc_strings) . ":" . $runtime_assoc_strings["left"] . ":" . $runtime_assoc_strings["right"] . ":" . $runtime_assoc_strings["empty"] . "\n";
$runtime_assoc_ints = array_map(strlen(...), array_combine(explode(",", "zero,one"), range(0, 1)));
echo count($runtime_assoc_ints) . ":" . $runtime_assoc_ints["zero"] . ":" . $runtime_assoc_ints["one"] . "\n";
$runtime_assoc_bools = array_map(strlen(...), array_combine(explode(",", "first,second"), array_fill(0, 2, true)));
echo count($runtime_assoc_bools) . ":" . $runtime_assoc_bools["first"] . ":" . $runtime_assoc_bools["second"] . "\n";
$runtime_assoc_floats = array_map(strlen(...), array_combine(explode(",", "first,second"), array_fill(0, 2, 0.0)));
echo count($runtime_assoc_floats) . ":" . $runtime_assoc_floats["first"] . ":" . $runtime_assoc_floats["second"] . "\n";
$runtime_assoc_nulls = array_map(strlen(...), array_combine(explode(",", "first,second"), array_fill(0, 2, null)));
echo count($runtime_assoc_nulls) . ":" . $runtime_assoc_nulls["first"] . ":" . $runtime_assoc_nulls["second"] . "\n";
"#,
    );
}

