#[test]
fn test_wasm32_web_e2e_matches_php_array_map_bool_float_callbacks() {
    assert_wasm_matches_php(
        r#"<?php
function keep_bool_value(bool $value): bool {
    return $value;
}
function positive_float(float $value): bool {
    return $value > 0.0;
}
$count = 3;
$bools = [false, true, true];
$floats = [-1.0, 0.0, 2.5];
$assigned_bools = $bools;
$assigned_floats = $floats;
$runtime_bools = array_fill(0, $count, true);
$runtime_floats = array_fill(0, $count, 1.25);
$assoc_bools = ["no" => false, "yes" => true];
$assoc_floats = ["neg" => -0.5, "pos" => 4.0];
$direct_bools = array_map("keep_bool_value", [false, true, true]);
$direct_floats = array_map(positive_float(...), [-1.0, 0.5, 2.0]);
$mapped_bools = array_map(keep_bool_value(...), $assigned_bools);
$mapped_floats = array_map("positive_float", $assigned_floats);
$runtime_bool_mapped = array_map("keep_bool_value", $runtime_bools);
$runtime_float_mapped = array_map(positive_float(...), $runtime_floats);
$assoc_bool_mapped = array_map("keep_bool_value", $assoc_bools);
$assoc_float_mapped = array_map(positive_float(...), $assoc_floats);
$bool_cb = keep_bool_value(...);
$bool_alias = $bool_cb;
$float_name = "positive_float";
$float_name_alias = $float_name;
$alias_bool_mapped = array_map($bool_alias, $assigned_bools);
$alias_float_mapped = array_map($float_name_alias, $assoc_floats);
echo count($direct_bools) . ":" . count($direct_floats) . "\n";
echo count($alias_bool_mapped) . ":" . ($alias_bool_mapped[0] ? "T" : "F") . ":" . count($alias_float_mapped) . ":" . ($alias_float_mapped["pos"] ? "T" : "F") . "\n";
foreach ($mapped_bools as $bool_key => $value) {
    echo $bool_key . "=" . ($value ? "T" : "F") . ",";
}
echo "\n";
foreach ($mapped_floats as $float_key => $value) {
    echo $float_key . "=" . ($value ? "T" : "F") . ",";
}
echo "\n";
echo count($runtime_bool_mapped) . ":" . ($runtime_bool_mapped[0] ? "T" : "F") . "\n";
echo count($runtime_float_mapped) . ":" . ($runtime_float_mapped[1] ? "T" : "F") . "\n";
foreach ($assoc_bool_mapped as $assoc_bool_key => $value) {
    echo $assoc_bool_key . "=" . ($value ? "T" : "F") . ",";
}
echo "\n";
foreach ($assoc_float_mapped as $assoc_float_key => $value) {
    echo $assoc_float_key . "=" . ($value ? "T" : "F") . ",";
}
echo "\n";
"#,
    );
}

