#[test]
fn test_wasm32_web_callable_resource_value_cells_are_rejected() {
    for (source, expected) in [
        (
            "<?php $a = [strlen(...)]; echo count($a);",
            "callable ownership runtime support",
        ),
        (
            "<?php $a = [function () { return 1; }]; echo count($a);",
            "callable ownership runtime support",
        ),
        (
            "<?php $a = [fopen(\"x\", \"w\")]; echo count($a);",
            "resource ownership runtime support",
        ),
    ] {
        let program = parse_program(source);
        let err = generate(&program, WasmOutputFormat::Wat)
            .expect_err("unsupported runtime value cells must not silently compile");

        assert!(err.message.contains(expected), "{}", err.message);
    }
}

#[test]
fn test_wasm32_web_object_callable_resource_string_coercions_are_rejected() {
    for (source, expected) in [
        (
            "<?php class Box {} echo (string) new Box();",
            "object string coercion",
        ),
        (
            "<?php echo \"x\" . strlen(...);",
            "callable string coercion",
        ),
        (
            "<?php echo (string) function () { return 1; };",
            "callable string coercion",
        ),
        (
            "<?php echo (string) fopen(\"x\", \"w\");",
            "resource string coercion",
        ),
        (
            "<?php class Box {} echo \"x\" == new Box();",
            "object string coercion",
        ),
        (
            "<?php echo \"x\" === strlen(...);",
            "callable string coercion",
        ),
        (
            "<?php echo \"x\" < fopen(\"x\", \"w\");",
            "resource string coercion",
        ),
        (
            "<?php class Box {} $s = (string) new Box(); echo $s;",
            "object string coercion",
        ),
        (
            "<?php function take(string $s): string { return $s; } echo take((string) strlen(...));",
            "callable string coercion",
        ),
        (
            "<?php function make(): string { return (string) fopen(\"x\", \"w\"); } echo make();",
            "resource string coercion",
        ),
        (
            "<?php class Box {} echo true ? (string) new Box() : \"x\";",
            "object string coercion",
        ),
        (
            "<?php echo true ? (string) strlen(...) : \"x\";",
            "callable string coercion",
        ),
        (
            "<?php echo match (1) { 1 => (string) fopen(\"x\", \"w\"), default => \"x\" };",
            "resource string coercion",
        ),
    ] {
        let program = parse_program(source);
        let err = generate(&program, WasmOutputFormat::Wat)
            .expect_err("unsupported object-like string coercion must not silently compile");

        assert!(err.message.contains(expected), "{}", err.message);
    }
}

#[test]
fn test_wasm32_web_object_callable_resource_string_builtin_args_are_rejected() {
    for (source, expected) in [
        (
            "<?php class Box {} echo strlen(new Box());",
            "object string coercion",
        ),
        (
            "<?php echo strtoupper(strlen(...));",
            "callable string coercion",
        ),
        (
            "<?php echo strtoupper(function () { return 1; });",
            "callable string coercion",
        ),
        (
            "<?php echo strlen(fopen(\"x\", \"w\"));",
            "resource string coercion",
        ),
        (
            "<?php class Box {} echo ord(new Box());",
            "object string coercion",
        ),
        (
            "<?php echo ord(strlen(...));",
            "callable string coercion",
        ),
        (
            "<?php echo ord(fopen(\"x\", \"w\"));",
            "resource string coercion",
        ),
        (
            "<?php class Box {} echo sprintf(\"%s\", new Box());",
            "object string coercion",
        ),
        (
            "<?php echo printf(\"%s\", strlen(...));",
            "callable string coercion",
        ),
        (
            "<?php echo sprintf(\"%s\", fopen(\"x\", \"w\"));",
            "resource string coercion",
        ),
        (
            "<?php class Box {} echo basename(new Box());",
            "object string coercion",
        ),
        (
            "<?php echo hash(\"md5\", strlen(...));",
            "callable string coercion",
        ),
        (
            "<?php echo str_contains(\"x\", fopen(\"x\", \"w\"));",
            "resource string coercion",
        ),
    ] {
        let program = parse_program(source);
        let err = generate(&program, WasmOutputFormat::Wat)
            .expect_err("unsupported object-like string builtin args must not silently compile");

        assert!(err.message.contains(expected), "{}", err.message);
    }
}

#[test]
fn test_wasm32_web_callable_ternary_different_targets_are_rejected() {
    let program = parse_program(
        "<?php
function ternary_left(int $x): int { return $x + 1; }
function ternary_right(int $x): int { return $x + 2; }
$cb = true ? ternary_left(...) : ternary_right(...);
echo $cb(1);
",
    );
    let err = generate(&program, WasmOutputFormat::Wat)
        .expect_err("different callable ternary targets must not silently compile");

    assert!(
        err.message
            .contains("wasm32-web callable ternaries require both arms to resolve to the same target"),
        "{}",
        err.message
    );
}

#[test]
fn test_wasm32_web_callable_ternary_different_instance_receivers_are_rejected() {
    let program = parse_program(
        "<?php
class TernaryReceiver {
    public function value(int $x): int { return $x + 1; }
}
$left = new TernaryReceiver();
$right = new TernaryReceiver();
$cb = true ? $left->value(...) : $right->value(...);
echo $cb(1);
",
    );
    let err = generate(&program, WasmOutputFormat::Wat)
        .expect_err("different callable ternary receivers must not silently compile");

    assert!(
        err.message
            .contains("wasm32-web callable ternary instance-method arms require the same receiver variable"),
        "{}",
        err.message
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_is_callable_ternary_different_instance_receivers() {
    assert_wasm_matches_php(
        "<?php
class IsCallableTernaryLeftReceiver {
    public function pick(bool $flag): bool { echo $flag ? \"left\\n\" : \"right\\n\"; return $flag; }
    public function value(int $x): int { return $x + 1; }
}
class IsCallableTernaryRightReceiver {
    public function value(string $x): string { return $x . \"!\"; }
}
$left = new IsCallableTernaryLeftReceiver();
$right = new IsCallableTernaryRightReceiver();
echo (is_callable($left->pick(true) ? $left->value(...) : $right->value(...)) ? 1 : 0) . \"\\n\";
echo (is_callable($left->pick(false) ? $left->value(...) : $right->value(...)) ? 1 : 0) . \"\\n\";
",
    );
}

