#[test]
fn test_wasm32_web_e2e_matches_php_callback_runtime_array_fill_returns() {
    assert_wasm_matches_php(
        r#"<?php
function runtime_callback_fill_ints(int $count): array {
    return array_fill(0, $count, 4);
}
function runtime_callback_value_fill_ints(int $count): array {
    $value = 5;
    return array_fill(0, $count, $value);
}
function runtime_callback_fill_strings(int $count): array {
    return array_fill(0, $count, "a");
}
function double_returned_fill(int $value): int {
    return $value * 2;
}
function wrap_returned_fill(string $value): string {
    return $value . "!";
}
$mapped_ints = array_map("double_returned_fill", runtime_callback_fill_ints(3));
$mapped_value_ints = array_map("double_returned_fill", runtime_callback_value_fill_ints(2));
$mapped_value_bools = array_map(is_int(...), runtime_callback_value_fill_ints(2));
$mapped_strings = array_map("wrap_returned_fill", runtime_callback_fill_strings(2));
foreach ($mapped_ints as $int_key => $int_value) {
    echo $int_key . "=" . $int_value . ",";
}
echo "\n";
foreach ($mapped_value_ints as $value_int_key => $value_int_value) {
    echo $value_int_key . "=" . $value_int_value . ",";
}
echo "\n";
foreach ($mapped_value_bools as $value_bool_key => $value_bool_value) {
    echo gettype($value_bool_key) . ":" . $value_bool_key . "=" . gettype($value_bool_value) . ":" . ($value_bool_value ? 1 : 0) . ",";
}
echo "\n";
foreach ($mapped_strings as $string_key => $string_value) {
    echo $string_key . "=" . $string_value . ",";
}
echo "\n";
foreach (array_map("double_returned_fill", runtime_callback_fill_ints(2)) as $key => $value) {
    echo gettype($key) . ":" . $key . "=" . gettype($value) . ":" . $value . ",";
}
echo "\n";
foreach (array_map("wrap_returned_fill", runtime_callback_fill_strings(2)) as $key => $value) {
    echo gettype($key) . ":" . $key . "=" . gettype($value) . ":" . $value . ",";
}
echo "\n";
"#,
    );
}

