#[test]
fn test_wasm32_web_array_map_two_arrays_unequal_lengths_is_rejected() {
    let program = parse_program(
        r#"<?php
function add_pair(int $left, int $right): int {
    return $left + $right;
}
$left = [1, 2];
$right = [10];
$mapped = array_map("add_pair", $left, $right);
"#,
    );
    let err = generate(&program, WasmOutputFormat::Wat)
        .expect_err("unequal multi-array array_map lengths need explicit null-fill support");

    assert!(err.message.contains("rejects unequal lengths"));
}

