#[test]
fn test_wasm32_web_callback_array_builtin_closures_are_rejected() {
    let cases = [
        (
            r#"<?php $mapped = array_map(fn(int $x): int => $x + 1, [1, 2]);"#,
            "array_map() currently requires a static string, direct first-class function callback, or simple callable variable alias",
        ),
        (
            r#"<?php $filtered = array_filter([1, 2], fn(int $x): bool => $x > 1);"#,
            "array_filter() currently requires a static string, direct first-class function callback, or simple callable variable alias",
        ),
        (
            r#"<?php $reduced = array_reduce([1, 2], fn(int $carry, int $value): int => $carry + $value, 0);"#,
            "array_reduce() currently requires a static string, direct first-class function callback, or simple callable variable alias",
        ),
        (
            r#"<?php $values = [1, 2]; array_walk($values, fn(int $x): int => $x);"#,
            "array_walk() currently requires a static string, direct first-class function callback, or simple callable variable alias",
        ),
        (
            r#"<?php $values = [2, 1]; usort($values, fn(int $a, int $b): int => $a - $b);"#,
            "usort() currently requires a static string, direct first-class function callback, or simple callable variable alias",
        ),
        (
            r#"<?php $values = ["b" => 2, "a" => 1]; uasort($values, fn(int $a, int $b): int => $a - $b);"#,
            "uasort() currently requires a static string, direct first-class function callback, or simple callable variable alias",
        ),
        (
            r#"<?php $values = ["b" => 2, "a" => 1]; uksort($values, fn(string $a, string $b): int => strcmp($a, $b));"#,
            "uksort() currently requires a static string, direct first-class function callback, or simple callable variable alias",
        ),
    ];

    for (source, expected) in cases {
        let program = parse_program(source);
        let err = generate(&program, WasmOutputFormat::Wat)
            .expect_err("closure callback array builtin must not silently compile");

        assert!(
            err.message.contains(expected),
            "expected error containing `{}`, got `{}`",
            expected,
            err.message
        );
    }
}

#[test]
fn test_wasm32_web_array_reduce_string_callback_null_values_are_rejected() {
    let source = r#"<?php
function join_word(string $carry, string $value): string {
    return $carry . $value;
}
$values = [null];
echo array_reduce($values, "join_word", "");
"#;
    let program = parse_program(source);
    let err = generate(&program, WasmOutputFormat::Wat)
        .expect_err("null value cells must not silently feed typed string reducer callbacks");

    assert!(
        err.message.contains(
            "array_reduce() currently supports string value-cell or associative arrays for string callbacks"
        ),
        "unexpected error: {}",
        err.message
    );
}

#[test]
fn test_wasm32_web_natural_sort_mutators_are_rejected() {
    for source in [
        r#"<?php $values = ["img10", "img2"]; natsort($values);"#,
        r#"<?php $values = ["Img10", "img2"]; natcasesort($values);"#,
    ] {
        let program = parse_program(source);
        let err = generate(&program, WasmOutputFormat::Wat)
            .expect_err("natural sort mutators need a real runtime comparator");

        assert!(
            err.message.contains(
                "natsort()/natcasesort() require natural string comparison runtime support"
            ),
            "unexpected error: {}",
            err.message
        );
    }
}

