#[test]
fn test_wasm32_web_e2e_matches_php_array_filter_dynamic_scalar_callback_name_helpers() {
    assert_wasm_matches_php(
        r#"<?php
function runtime_true(): bool { return strlen("yes") === 3; }
function runtime_false(): bool { return strlen("no") === 3; }
function bool_filter_name(bool $flag): string { return $flag ? "keep_true_value" : "drop_true_value"; }
function float_filter_name(bool $flag): string { return $flag ? "keep_nonzero_float_dynamic" : "keep_positive_float_dynamic"; }
function string_filter_name(bool $flag): string { return $flag ? "keep_long_string_dynamic" : "keep_short_string_dynamic"; }
function keep_true_value(bool $value): bool { return $value; }
function drop_true_value(bool $value): bool { return !$value; }
function keep_nonzero_float_dynamic(float $value): bool { return $value != 0.0; }
function keep_positive_float_dynamic(float $value): bool { return $value > 0.0; }
function keep_long_string_dynamic(string $value): bool { return strlen($value) > 1; }
function keep_short_string_dynamic(string $value): bool { return strlen($value) === 1; }
$bools = [false, true, true];
$floats = [0.0, 1.5, -2.0];
$words = ["a", "bb", "ccc"];
$direct_bools = array_filter([false, true, true], bool_filter_name(runtime_true()));
$direct_floats = array_filter([0.0, 1.5, -2.0], float_filter_name(runtime_false()));
$direct_words = array_filter(["a", "bb", "ccc"], string_filter_name(runtime_true()));
$assigned_bools = array_filter($bools, bool_filter_name(runtime_false()));
$assigned_floats = array_filter($floats, float_filter_name(runtime_true()));
$assigned_words = array_filter($words, string_filter_name(runtime_false()));
echo count($direct_bools) . ":" . count($direct_floats) . ":" . count($direct_words) . "\n";
echo count($assigned_bools) . ":" . count($assigned_floats) . ":" . count($assigned_words) . "\n";
foreach ($direct_bools as $key => $value) {
    echo $key . "=" . ($value ? "T" : "F") . ",";
}
echo "\n";
foreach ($direct_floats as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
foreach ($direct_words as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
foreach ($assigned_bools as $key => $value) {
    echo $key . "=" . ($value ? "T" : "F") . ",";
}
echo "\n";
foreach ($assigned_floats as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
foreach ($assigned_words as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
"#,
    );
}

