#[test]
fn test_wasm32_web_e2e_matches_php_uasort_direct_dynamic_bool_callback_name_helpers() {
    assert_wasm_matches_php(
        r#"<?php
function runtime_true(): bool { return strlen("yes") === 3; }
function runtime_false(): bool { return strlen("no") === 3; }
function sort_name(bool $flag): string { echo "bool-value-sort-pick\n"; return $flag ? "sort_bool_true_first" : "sort_bool_false_first"; }
function sort_bool_true_first(bool $left, bool $right): int {
    if ($left === $right) {
        return 0;
    }
    if ($left) {
        return -1;
    }
    return 1;
}
function sort_bool_false_first(bool $left, bool $right): int {
    if ($left === $right) {
        return 0;
    }
    if ($left) {
        return 1;
    }
    return -1;
}
function show_bools(array $values): void {
    foreach ($values as $value) {
        if ($value) {
            echo "T";
        } else {
            echo "F";
        }
    }
    echo "\n";
}
$assoc_true = ["b" => false, "a" => true, "c" => false];
$ok_true = uasort($assoc_true, sort_name(runtime_true()));
if ($ok_true) {
    echo "1:";
} else {
    echo "0:";
}
show_bools($assoc_true);
$assoc_false = ["b" => false, "a" => true, "c" => false];
$ok_false = uasort($assoc_false, sort_name(runtime_false()));
if ($ok_false) {
    echo "1:";
} else {
    echo "0:";
}
show_bools($assoc_false);
"#,
    );
}

#[test]
fn test_wasm32_web_uasort_direct_dynamic_callback_name_missing_target_is_rejected() {
    let source = r#"<?php
function runtime_flag(): bool { return strlen("yes") === 3; }
function sort_name(bool $flag): string { return $flag ? "sort_asc" : "missing"; }
function sort_asc(int $left, int $right): int { return $left - $right; }
$values = ["b" => 2, "a" => 1];
uasort($values, sort_name(runtime_flag()));
"#;
    let program = parse_program(source);
    let err = generate(&program, WasmOutputFormat::Wat)
        .expect_err("dynamic uasort callback helper with missing target must not silently compile");

    assert!(
        err.message.contains(
            "dynamic uasort() callback helper can only return declared user functions"
        ),
        "unexpected error: {}",
        err.message
    );
}

