#[test]
fn test_wasm32_web_e2e_matches_php_callback_array_builtins_direct_function_call_names() {
    assert_wasm_matches_php(
        r#"<?php
function map_name(bool $flag): string { echo "map-name\n"; return $flag ? "map_it" : "other"; }
function filter_name(bool $flag): string { echo "filter-name\n"; return $flag ? "keep_it" : "other"; }
function reduce_name(bool $flag): string { echo "reduce-name\n"; return $flag ? "sum_it" : "other"; }
function reduce_string_name(bool $flag): string { echo "reduce-string-name\n"; return $flag ? "join_it" : "other"; }
function walk_name(bool $flag): string { echo "walk-name\n"; return $flag ? "show_it" : "other"; }
function sort_name(bool $flag): string { echo "sort-name\n"; return $flag ? "sort_it" : "other"; }
function key_sort_name(bool $flag): string { echo "key-sort-name\n"; return $flag ? "key_sort_it" : "other"; }
function map_it(int $x): int { return $x + 1; }
function keep_it(int $x): bool { return $x > 1; }
function sum_it(int $carry, int $value): int { return $carry + $value; }
function join_it(string $carry, string $value): string { return $carry . "[" . $value . "]"; }
function show_it(int $value): int { echo $value . ","; return 0; }
function sort_it(int $left, int $right): int { return $left - $right; }
function key_sort_it(string $left, string $right): int { return strcmp($left, $right); }
$mapped = array_map(map_name(true), [1, 2]);
echo count($mapped) . ":" . $mapped[0] . ":" . $mapped[1] . "\n";
$filtered = array_filter([1, 2, 3], filter_name(true));
echo count($filtered) . ":" . $filtered[1] . ":" . $filtered[2] . "\n";
echo array_reduce([1, 2], reduce_name(true), 10) . "\n";
$joined = array_reduce(["a", "bb"], reduce_string_name(true), "");
echo $joined . ":" . strlen($joined) . "\n";
$walked = [4, 5];
echo (array_walk($walked, walk_name(true)) ? 1 : 0) . "\n";
$sorted = [3, 1, 2];
echo (usort($sorted, sort_name(true)) ? 1 : 0) . ":" . $sorted[0] . "," . $sorted[1] . "," . $sorted[2] . "\n";
$assoc = ["b" => 2, "a" => 1];
echo (uasort($assoc, sort_name(true)) ? 1 : 0) . ":";
foreach ($assoc as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
$assoc_keys = ["b" => 2, "a" => 1];
echo (uksort($assoc_keys, key_sort_name(true)) ? 1 : 0) . ":";
foreach ($assoc_keys as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_callback_array_builtins_direct_scalar_function_call_names() {
    assert_wasm_matches_php(
        r#"<?php
function map_name_by_mode(int $mode): string { echo "map-mode\n"; return $mode === 2 ? "map_it" : "other"; }
function filter_name_by_text(string $text): string { echo "filter-text\n"; return $text === "keep" ? "keep_it" : "other"; }
function reduce_name_by_ratio(float $ratio): string { echo "reduce-ratio\n"; return $ratio >= 1.5 ? "sum_it" : "other"; }
function reduce_string_name_by_ratio(float $ratio): string { echo "reduce-string-ratio\n"; return $ratio >= 1.5 ? "join_it" : "other"; }
function walk_name_by_mode(int $mode): string { echo "walk-mode\n"; return $mode === 7 ? "show_it" : "other"; }
function sort_name_by_text(string $text): string { echo "sort-text\n"; return $text === "sort" ? "sort_it" : "other"; }
function key_sort_name_by_ratio(float $ratio): string { echo "key-sort-ratio\n"; return $ratio >= 2.5 ? "key_sort_it" : "other"; }
function map_it(int $x): int { return $x + 1; }
function keep_it(int $x): bool { return $x > 1; }
function sum_it(int $carry, int $value): int { return $carry + $value; }
function join_it(string $carry, string $value): string { return $carry . "[" . $value . "]"; }
function show_it(int $value): int { echo $value . ","; return 0; }
function sort_it(int $left, int $right): int { return $left - $right; }
function key_sort_it(string $left, string $right): int { return strcmp($left, $right); }
$mapped = array_map(map_name_by_mode(2), [1, 2]);
echo count($mapped) . ":" . $mapped[0] . ":" . $mapped[1] . "\n";
$filtered = array_filter([1, 2, 3], filter_name_by_text("keep"));
echo count($filtered) . ":" . $filtered[1] . ":" . $filtered[2] . "\n";
echo array_reduce([1, 2], reduce_name_by_ratio(1.5), 10) . "\n";
$joined = array_reduce(["a", "bb"], reduce_string_name_by_ratio(1.5), "");
echo $joined . ":" . strlen($joined) . "\n";
$walked = [4, 5];
echo (array_walk($walked, walk_name_by_mode(7)) ? 1 : 0) . "\n";
$sorted = [3, 1, 2];
echo (usort($sorted, sort_name_by_text("sort")) ? 1 : 0) . ":" . $sorted[0] . "," . $sorted[1] . "," . $sorted[2] . "\n";
$assoc = ["b" => 2, "a" => 1];
echo (uasort($assoc, sort_name_by_text("sort")) ? 1 : 0) . ":";
foreach ($assoc as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
$assoc_keys = ["b" => 2, "a" => 1];
echo (uksort($assoc_keys, key_sort_name_by_ratio(2.5)) ? 1 : 0) . ":";
foreach ($assoc_keys as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_callback_array_builtins_assigned_scalar_function_call_names() {
    assert_wasm_matches_php(
        r#"<?php
function map_name_by_mode(int $mode): string { echo "map-mode\n"; return $mode === 2 ? "map_it" : "other"; }
function filter_name_by_text(string $text): string { echo "filter-text\n"; return $text === "keep" ? "keep_it" : "other"; }
function reduce_name_by_ratio(float $ratio): string { echo "reduce-ratio\n"; return $ratio >= 1.5 ? "sum_it" : "other"; }
function reduce_string_name_by_ratio(float $ratio): string { echo "reduce-string-ratio\n"; return $ratio >= 1.5 ? "join_it" : "other"; }
function walk_name_by_mode(int $mode): string { echo "walk-mode\n"; return $mode === 7 ? "show_it" : "other"; }
function sort_name_by_text(string $text): string { echo "sort-text\n"; return $text === "sort" ? "sort_it" : "other"; }
function key_sort_name_by_ratio(float $ratio): string { echo "key-sort-ratio\n"; return $ratio >= 2.5 ? "key_sort_it" : "other"; }
function map_it(int $x): int { return $x + 1; }
function keep_it(int $x): bool { return $x > 1; }
function sum_it(int $carry, int $value): int { return $carry + $value; }
function join_it(string $carry, string $value): string { return $carry . "[" . $value . "]"; }
function show_it(int $value): int { echo $value . ","; return 0; }
function sort_it(int $left, int $right): int { return $left - $right; }
function key_sort_it(string $left, string $right): int { return strcmp($left, $right); }
$map_cb = map_name_by_mode(2);
$map_alias = $map_cb;
$mapped = array_map($map_alias, [1, 2]);
echo count($mapped) . ":" . $mapped[0] . ":" . $mapped[1] . "\n";
$filter_cb = filter_name_by_text("keep");
$filtered = array_filter([1, 2, 3], $filter_cb);
echo count($filtered) . ":" . $filtered[1] . ":" . $filtered[2] . "\n";
$reduce_cb = reduce_name_by_ratio(1.5);
echo array_reduce([1, 2], $reduce_cb, 10) . "\n";
$reduce_string_cb = reduce_string_name_by_ratio(1.5);
$reduce_string_alias = $reduce_string_cb;
$joined = array_reduce(["a", "bb"], $reduce_string_alias, "");
echo $joined . ":" . strlen($joined) . "\n";
$walk_cb = walk_name_by_mode(7);
$walk_alias = $walk_cb;
$walked = [4, 5];
echo (array_walk($walked, $walk_alias) ? 1 : 0) . "\n";
$sort_cb = sort_name_by_text("sort");
$sort_alias = $sort_cb;
$sorted = [3, 1, 2];
echo (usort($sorted, $sort_alias) ? 1 : 0) . ":" . $sorted[0] . "," . $sorted[1] . "," . $sorted[2] . "\n";
$assoc = ["b" => 2, "a" => 1];
echo (uasort($assoc, $sort_alias) ? 1 : 0) . ":";
foreach ($assoc as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
$key_sort_cb = key_sort_name_by_ratio(2.5);
$key_sort_alias = $key_sort_cb;
$assoc_keys = ["b" => 2, "a" => 1];
echo (uksort($assoc_keys, $key_sort_alias) ? 1 : 0) . ":";
foreach ($assoc_keys as $key => $value) {
    echo $key . "=" . $value . ",";
}
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_callback_array_builtin_static_method_callables() {
    assert_wasm_matches_php(
        r#"<?php
class CallbackBox {
    public static function mapIt(int $x): int { return $x + 1; }
    public static function keepIt(int $x): bool { return $x > 1; }
    public static function sumIt(int $carry, int $value): int { return $carry + $value; }
    public static function walkIt(int $value, int $key): int { echo $key . "=" . $value . ","; return $value; }
    public static function sortIt(int $a, int $b): int { return $a - $b; }
    public static function sortKey(string $a, string $b): int { return strcmp($a, $b); }
}
$mapped = array_map(CallbackBox::mapIt(...), [1, 2]);
foreach ($mapped as $value) { echo $value . ","; }
echo "\n";
echo call_user_func(CallbackBox::mapIt(...), 4) . "\n";
echo call_user_func_array(CallbackBox::sumIt(...), [5, 6]) . "\n";
$filtered = array_filter([1, 2], CallbackBox::keepIt(...));
foreach ($filtered as $key => $value) { echo $key . "=" . $value . ","; }
echo "\n";
echo array_reduce([1, 2], CallbackBox::sumIt(...), 0) . "\n";
$walked = [1, 2];
array_walk($walked, CallbackBox::walkIt(...));
echo "\n";
$values = [2, 1];
$sort = CallbackBox::sortIt(...);
usort($values, $sort);
foreach ($values as $value) { echo $value . ","; }
echo "\n";
$assoc = ["b" => 2, "a" => 1];
uasort($assoc, CallbackBox::sortIt(...));
foreach ($assoc as $key => $value) { echo $key . "=" . $value . ","; }
echo "\n";
$keys = ["b" => 2, "a" => 1];
uksort($keys, CallbackBox::sortKey(...));
foreach ($keys as $key => $value) { echo $key . "=" . $value . ","; }
echo "\n";
"#,
    );
}

