#[test]
fn test_wasm32_web_e2e_matches_php_dynamic_associative_array_merge_direct_value_set_ops() {
    assert_wasm_matches_php(
        r#"<?php
$source = ["a" => "red", 4 => "green", "b" => "blue"];
$diff_mask = ["drop" => "red"];
$intersect_mask = ["keep1" => "green", "keep2" => "blue"];
$left = array_merge(["x" => "before"], array_diff($source, $diff_mask), ["tail" => "done"]);
echo count($left) . ":" . $left["x"] . ":" . $left[0] . ":" . $left["b"] . ":" . $left["tail"] . "\n";
$left_keys = array_keys($left);
echo $left_keys[0] . ":" . $left_keys[1] . ":" . $left_keys[2] . ":" . $left_keys[3] . "\n";
$right = array_merge(["x" => "before"], array_intersect($source, $intersect_mask), ["tail" => "done"]);
echo count($right) . ":" . $right["x"] . ":" . $right[0] . ":" . $right["b"] . ":" . $right["tail"] . "\n";
$right_keys = array_keys($right);
echo $right_keys[0] . ":" . $right_keys[1] . ":" . $right_keys[2] . ":" . $right_keys[3] . "\n";
$keys = explode(",", "first,second,third");
$values = explode(",", "keep,drop,keep");
$direct_diff = array_merge(["start" => "ok"], array_diff(array_combine($keys, $values), ["drop"]));
echo count($direct_diff) . ":" . $direct_diff["start"] . ":" . $direct_diff["first"] . ":" . $direct_diff["third"] . "\n";
$direct_intersect = array_merge(["start" => "ok"], array_intersect(array_fill_keys($keys, "keep"), ["keep"]));
echo count($direct_intersect) . ":" . $direct_intersect["start"] . ":" . $direct_intersect["first"] . ":" . $direct_intersect["second"] . ":" . $direct_intersect["third"] . "\n";
"#,
    );
}

