#[test]
fn test_wasm32_web_empty_string_offset_assignment_is_rejected() {
    let program = parse_program("<?php $s = \"abc\"; $s[1] = \"\"; echo $s;");
    let err = generate(&program, WasmOutputFormat::Wat)
        .expect_err("empty string offset assignment must not silently compile");

    assert!(err.message.contains("cannot assign an empty string"));
}

#[test]
fn test_wasm32_web_binary_output_uses_wat2wasm() {
    let program = parse_program("<?php echo \"hello\";");
    match generate(&program, WasmOutputFormat::Wasm) {
        Ok(bytes) => assert_eq!(&bytes[..4], b"\0asm"),
        Err(err) => assert!(err.message.contains("wat2wasm is required")),
    }
}

