#[test]
fn test_wasm32_web_e2e_matches_php_string_function_params_and_returns() {
    assert_wasm_matches_php(
        r#"<?php
function ident(string $value): string {
    return $value;
}
function suffix(string $value, string $tail = "!"): string {
    return $tail;
}
$name = "web";
echo ident($name) . "\n";
echo ident("literal") . "\n";
echo suffix($name) . "\n";
echo suffix(tail: "?", value: $name) . "\n";
$copy = ident($name);
echo $copy . ":" . strlen($copy) . "\n";
echo strlen(ident($name)) . ":" . ord(ident("W")) . "\n";
echo (str_contains(ident($name), "e") ? 1 : 0) . ",";
echo (str_contains($name, ident("e")) ? 1 : 0) . ",";
echo (str_starts_with(ident($name), "we") ? 1 : 0) . ",";
echo (str_ends_with(ident($name), "eb") ? 1 : 0) . ",";
echo (ctype_alpha(ident("Web")) ? 1 : 0) . "\n";
echo strtoupper(ident($name)) . ":" . strrev(ident($name)) . ":" . urlencode(ident("w eb")) . "\n";
echo base64_encode(ident($name)) . ":" . base64_decode(ident("d2Vi")) . "\n";
echo htmlspecialchars(ident("<a&b>"), ENT_QUOTES, "UTF-8") . "\n";
echo trim(ident(" web "), ident(" ")) . ":" . substr(ident("webasm"), 3) . "\n";
echo str_replace(ident("web"), ident("WASM"), ident("web target")) . "\n";
echo str_pad(ident("web"), 5, ident("."), STR_PAD_LEFT) . "\n";
echo substr_replace(ident("webasm"), ident("X"), 3, 3) . "\n";
echo wordwrap(ident("web asm"), 3, ident("|"), true) . "\n";
echo strstr(ident("webasm"), ident("asm")) . "\n";
echo basename(ident("/tmp/web.php"), ident(".php")) . ":" . dirname(ident("/tmp/web.php")) . ":" . pathinfo(ident("/tmp/web.php"), PATHINFO_FILENAME) . "\n";
echo (ident("web") === ident($name) ? 1 : 0) . ",";
echo strcmp(ident("web"), ident("wasm")) . ",";
echo strcasecmp(ident("WEB"), ident("web")) . "\n";
echo strpos(ident("webasm"), ident("asm")) . ":" . strrpos(ident("webasmweb"), ident("web")) . "\n";
echo gettype(ident($name)) . ":" . (is_string(ident($name)) ? 1 : 0) . "\n";
"#,
    );
}

