#[test]
fn test_wasm32_web_typed_string_bool_float_locals() {
    assert_wasm_stdout(
        r#"<?php
function typed_local_join(string $value): string {
    return $value . "!";
}

function typed_local_pick(bool $flag): string {
    return $flag ? "yes" : "no";
}

function typed_local_scale(float $value): float {
    return $value * 2.0;
}

string $name = "web";
bool $flag = strlen($name) === 3;
float $score = 1.25;

echo typed_local_join($name) . "\n";
echo typed_local_pick($flag) . "\n";
echo typed_local_scale($score) . "\n";

$name[0] = "W";
$flag = str_contains($name, "e");
$score = $score + 0.75;

echo $name . ":" . ($flag ? 1 : 0) . ":" . $score . "\n";
"#,
        "web!\nyes\n2.5\nWeb:1:2\n",
    );
}

