#[test]
fn test_wasm32_web_pipe_closure_literal_is_rejected() {
    let program = parse_program("<?php echo 7 |> (fn($v) => $v + 1);");
    let err = generate(&program, WasmOutputFormat::Wat)
        .expect_err("wasm pipe closure literal must not silently compile");
    assert!(
        err.message
            .contains("wasm32-web expression calls require a supported invokable object")
    );
}

