#[test]
fn test_wasm32_web_static_nonnumeric_string_operations_are_rejected() {
    for source in [
        r#"<?php echo "web" + 1;"#,
        r#"<?php echo 1 - "web";"#,
        r#"<?php echo "web" & 1;"#,
    ] {
        let program = parse_program(source);
        let err = generate(&program, WasmOutputFormat::Wat)
            .expect_err("non-numeric static strings must not silently compile as zero");

        assert!(
            err.message.contains("leading-numeric string"),
            "{}",
            err.message
        );
    }
}

