#[test]
fn test_wasm32_web_e2e_matches_php_escape_helpers_string_values() {
    assert_wasm_matches_php(
        r##"<?php
function ident(string $s): string {
    return $s;
}
function wrap(string $s): string {
    return "[" . $s . "]";
}
$quote = "a'b\"c\\d";
$escaped = addslashes(ident($quote));
echo $escaped . "\n";
echo $escaped[1] . ":" . strlen($escaped) . ":" . ord($escaped[2]) . "\n";
echo wrap($escaped) . "\n";
$escaped[0] = "#";
echo $escaped . "\n";
$slash = "a\\'b\\\\c";
$plain = stripslashes(ident($slash));
echo $plain . "\n";
echo $plain[1] . ":" . strlen($plain) . ":" . ord($plain[2]) . "\n";
echo wrap($plain) . "\n";
$plain[0] = "#";
echo $plain . "\n";
$lines = "a\nb\r\nc\rd";
$html = nl2br(ident($lines));
echo $html . "\n";
echo $html[1] . ":" . strlen($html) . ":" . ord($html[5]) . "\n";
echo wrap($html) . "\n";
$html[0] = "#";
echo $html . "\n";
"##,
    );
}

