#[test]
fn test_wasm32_web_sscanf_unsupported_scan_conversions_are_rejected() {
    for source in [
        "<?php echo implode(\"|\", sscanf(\"1.25\", \"%G\"));",
        "<?php echo implode(\"|\", sscanf(\"abc\", \"%q\"));",
    ] {
        let program = parse_program(source);
        let err = generate(&program, WasmOutputFormat::Wat)
            .expect_err("unsupported sscanf conversion must not silently compile");

        assert!(
            err.message.contains("sscanf() does not support scan conversion"),
            "{}",
            err.message
        );
    }
}

