#[test]
fn test_wasm32_web_e2e_matches_php_empty_builtin() {
    assert_wasm_matches_php(
        r#"<?php
$empty = "";
$zero = "0";
$text = "web";
echo (empty($empty) ? 1 : 0) . ",";
echo (empty($zero) ? 1 : 0) . ",";
echo (empty($text) ? 1 : 0) . "\n";
echo (empty(0) ? 1 : 0) . ",";
echo (empty(42) ? 1 : 0) . ",";
echo (empty(null) ? 1 : 0) . ",";
echo (empty(false) ? 1 : 0) . ",";
echo (empty(true) ? 1 : 0) . "\n";
function ident(string $s): string { return $s; }
echo (empty(ident("")) ? 1 : 0) . ",";
echo (empty(ident("0")) ? 1 : 0) . ",";
echo (empty(ident("web")) ? 1 : 0) . "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_is_numeric_builtin() {
    assert_wasm_matches_php(
        r#"<?php
echo (is_numeric(42) ? 1 : 0) . ",";
echo (is_numeric(3.5) ? 1 : 0) . ",";
echo (is_numeric(true) ? 1 : 0) . ",";
echo (is_numeric(null) ? 1 : 0) . "\n";
echo (is_numeric("12.5") ? 1 : 0) . ",";
echo (is_numeric(" 1e3 ") ? 1 : 0) . ",";
echo (is_numeric("web") ? 1 : 0) . ",";
echo (is_numeric("") ? 1 : 0) . "\n";
$a = " -12.5e+2 ";
$b = ".5";
$c = "1e";
$d = "+";
echo (is_numeric($a) ? 1 : 0) . ",";
echo (is_numeric($b) ? 1 : 0) . ",";
echo (is_numeric($c) ? 1 : 0) . ",";
echo (is_numeric($d) ? 1 : 0) . "\n";
function ident(string $s): string { return $s; }
echo (is_numeric(ident("123")) ? 1 : 0) . ",";
echo (is_numeric(ident("web")) ? 1 : 0) . ",";
echo (is_numeric(ident($a)) ? 1 : 0) . "\n";
"#,
    );
}

