#[test]
fn test_wasm32_web_e2e_matches_php_string_ternary_and_match_values() {
    assert_wasm_matches_php(
        r#"<?php
function choose(bool $flag, string $left, string $right): string {
    return $flag ? $left . "!" : $right . "?";
}
function label(int $kind): string {
    return match ($kind) {
        1 => "one",
        2, 3 => "few",
        default => "many",
    };
}
function wrap(string $s): string {
    return "<" . $s . ">";
}
function choose_short(string $left, string $right): string {
    return $left ?: $right;
}
$a = "web";
$b = "asm";
$picked = true ? $a . "-" : $b . "-";
echo $picked . ":" . $picked[1] . ":" . strlen($picked) . "\n";
echo wrap(false ? $a : $b) . "\n";
echo wrap($a ?: $b) . "\n";
echo choose(false, $a, $b) . "\n";
echo choose_short("", $b) . "\n";
$short = $a ?: $b;
$zero = "0";
echo ($short . ":" . ($zero ?: $b)) . "\n";
$matched = match (2) {
    1 => $a . "1",
    2 => $b . "2",
    default => "none",
};
echo $matched . ":" . ord($matched[0]) . "\n";
$matched[0] = "A";
echo $matched . "\n";
"#,
    );
}

