fn test_wasm32_web_e2e_matches_php_static_string_builtin_expression_args() {
    assert_wasm_matches_php(
        r#"<?php
const PART = "asm";
echo trim(" " . PART . " ") . "\n";
echo substr("web" . PART, 3) . "\n";
echo substr_replace("web" . PART, "X" . PART, 3, 3) . "\n";
echo str_replace("w" . "e", "W" . "E", "web" . PART) . "\n";
echo str_ireplace("WEB", "W" . "E", "web" . PART) . "\n";
echo strstr("web" . PART, "b" . PART) . "\n";
echo wordwrap("web " . PART, 3, "|" . "|", true) . "\n";
echo md5("web" . PART) . "\n";
echo sha1("web" . PART) . "\n";
echo hash("sha256", "web" . PART) . "\n";
echo basename("/tmp/" . PART . ".php", ".p" . "hp") . "\n";
echo dirname("/tmp/" . PART . "/file.php", 1) . "\n";
echo pathinfo("/tmp/" . PART . ".php", PATHINFO_FILENAME) . "\n";
echo json_encode("web" . PART) . "\n";
"#,
    );
}

