#[test]
fn test_wasm32_web_e2e_matches_php_uasort_runtime_assoc_direct_instance_method_callable_scalar_values() {
    assert_wasm_matches_php(
        r#"<?php
class RuntimeAssocStringSorter {
    public int $direction;

    public function __construct(int $direction) {
        $this->direction = $direction;
    }

    public function compare(string $left, string $right): int {
        return strcmp($left, $right) * $this->direction;
    }
}

class RuntimeAssocFloatSorter {
    public int $direction;

    public function __construct(int $direction) {
        $this->direction = $direction;
    }

    public function compare(float $left, float $right): int {
        if ($left === $right) {
            return 0;
        }
        return ($left < $right ? -1 : 1) * $this->direction;
    }
}

class RuntimeAssocBoolSorter {
    public bool $trueFirst;

    public function __construct(bool $trueFirst) {
        $this->trueFirst = $trueFirst;
    }

    public function compare(bool $left, bool $right): int {
        if ($left === $right) {
            return 0;
        }
        if ($this->trueFirst) {
            return $left ? -1 : 1;
        }
        return $left ? 1 : -1;
    }
}

$keys = explode(",", "first,second,third,fourth");

$strings = array_combine($keys, explode(",", "pear,apple,plum,fig"));
uasort($strings, (new RuntimeAssocStringSorter(-1))->compare(...));
foreach ($strings as $key => $value) {
    echo "[" . $key . ":" . $value . "]";
}
echo "\n";

$floats = array_combine($keys, [2.5, 4.25, 1.75, 3.5]);
uasort($floats, (new RuntimeAssocFloatSorter(-1))->compare(...));
foreach ($floats as $key => $value) {
    echo "[" . $key . ":" . $value . "]";
}
echo "\n";

$bools = array_combine($keys, [false, true, false, true]);
uasort($bools, (new RuntimeAssocBoolSorter(true))->compare(...));
foreach ($bools as $key => $value) {
    echo "[" . $key . ":" . ($value ? "T" : "F") . "]";
}
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_uksort_runtime_assoc_int_keys() {
    assert_wasm_matches_php(
        r#"<?php
function keep_uksort_runtime_int(int $value): bool {
    return $value > 1;
}
function cmp_uksort_runtime_int(int $left, int $right): int {
    if ($left < $right) {
        return 1;
    }
    if ($left > $right) {
        return -1;
    }
    return 0;
}
$start = 1;
$end = 5;
$items = array_filter(range($start, $end), "keep_uksort_runtime_int");
uksort($items, "cmp_uksort_runtime_int");
echo json_encode($items);
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_uksort_runtime_assoc_string_keys() {
    assert_wasm_matches_php(
        r#"<?php
function cmp_uksort_runtime_string(string $left, string $right): int {
    if ($left < $right) {
        return 1;
    }
    if ($left > $right) {
        return -1;
    }
    return 0;
}
$csv = "pear,fig,plum,fig";
$items = array_fill_keys(explode(",", $csv), 3);
uksort($items, "cmp_uksort_runtime_string");
echo count($items) . ":" . json_encode($items);
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_uksort_runtime_assoc_direct_instance_method_callable_string_keys() {
    assert_wasm_matches_php(
        r#"<?php
class RuntimeAssocKeySorter {
    public int $direction;

    public function __construct(int $direction) {
        $this->direction = $direction;
    }

    public function compare(string $left, string $right): int {
        return strcmp($left, $right) * $this->direction;
    }
}

$keys = explode(",", "pear,fig,plum,date");
$items = array_fill_keys($keys, 3);
uksort($items, (new RuntimeAssocKeySorter(-1))->compare(...));
foreach ($items as $key => $value) {
    echo "[" . $key . ":" . $value . "]";
}
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_uksort_runtime_int_keys_float_callback() {
    assert_wasm_matches_php(
        r#"<?php
function keep_uksort_runtime_float_key(int $value): bool {
    return $value > 1;
}
function cmp_uksort_runtime_float_key(float $left, float $right): int {
    if ($left < $right) {
        return 1;
    }
    if ($left > $right) {
        return -1;
    }
    return 0;
}
$start = 1;
$end = 5;
$items = array_filter(range($start, $end), keep_uksort_runtime_float_key(...));
uksort($items, "cmp_uksort_runtime_float_key");
echo json_encode($items);
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_direct_runtime_string_key_assoc_foreach() {
    assert_wasm_matches_php(
        r#"<?php
$csv = "pear,fig,plum,fig";
foreach (array_fill_keys(explode(",", $csv), 2) as $key => $value) {
    echo "[" . $key . ":" . $value . "]";
}
echo "\n";
"#,
    );
}

