#[test]
fn test_wasm32_web_e2e_matches_php_float_math() {
    assert_wasm_matches_php(
        r#"<?php
$x = 7 / 2;
echo $x . "\n";
echo floor(3.9) . "," . ceil(3.1) . "," . sqrt(16) . "\n";
echo pi() > 3 ? 1 : 0;
echo "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_fdiv_builtin() {
    assert_wasm_matches_php(
        r#"<?php
echo fdiv(7, 2) . "\n";
echo (is_infinite(fdiv(1, 0)) ? 1 : 0) . ",";
echo (is_nan(fdiv(0, 0)) ? 1 : 0) . "\n";
"#,
    );
}

#[test]
fn test_wasm32_web_e2e_matches_php_scalar_compound_assignments() {
    assert_wasm_matches_php(
        r#"<?php
$x = 4;
$x += 3;
$x *= 2;
$x &= 14;
$x <<= 1;
echo $x . "\n";
$y = 9;
$y -= 4;
$y %= 3;
$y |= 8;
$y ^= 2;
$y >>= 1;
echo $y . "\n";
$z = 7;
$z /= 2;
echo $z . "\n";
$p = 2;
$p **= 5;
echo $p . "\n";
"#,
    );
}
